// Package accordion provides a shadcn/ui-style Accordion: a column of
// sections in a bordered box, one above the other, that a click opens and
// closes, as do Enter and Space, and that the Up and Down arrows move
// between. Each section keeps its own open state, so several may be open
// at once.
//
//	accordion.Accordion(c, accordion.Props{
//		Items: []accordion.Item{
//			{Title: "General", Open: &app.general, Build: buildGeneral},
//			{Title: "Privacy", Open: &app.privacy, Build: buildPrivacy},
//		},
//	})
//
// To keep one section open at a time, close the others as one opens, as
// this registry does in its examples: build the sections with
// AccordionItem and an index of the one open:
//
//	for i, s := range sections {
//		open := app.section == i
//		if accordion.AccordionItem(c, accordion.Item{Title: s, Open: &open}).Changed() {
//			app.section = -1
//			if open {
//				app.section = i
//			}
//		}
//	}
package accordion

import "github.com/egoist/mygo/ui"

// Item is one section of an Accordion: a header showing Title, which a
// click opens and closes, and below it what Build draws while *Open is
// true.
type Item struct {
	// Title is the text of the header, such as "General".
	Title string
	// Open is whether the section is open.
	Open *bool
	// Build draws the content of the section while it is open.
	Build func(c *ui.Context)
}

// Props describes the accordion to draw.
type Props struct {
	// Items are the sections of the accordion, in order.
	Items []Item
	// Disabled keeps the sections from opening and closing.
	Disabled bool
}

// Accordion draws the sections in a bordered box and returns it, so a
// view can chain more calls on it.
func Accordion(c *ui.Context, p Props) *ui.Element {
	e := ui.Accordion(c, func() {
		for _, it := range p.Items {
			ui.AccordionItem(c, it.Title, it.Open, func() {
				if it.Build != nil {
					it.Build(c)
				}
			})
		}
	})
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// AccordionItem builds one section of an Accordion, for a view that
// keeps one open at a time, or that builds its sections itself.
func AccordionItem(c *ui.Context, it Item) *ui.Element {
	return ui.AccordionItem(c, it.Title, it.Open, func() {
		if it.Build != nil {
			it.Build(c)
		}
	})
}

// Package alert provides a shadcn/ui-style Alert: a colored notice with
// a bold title and an optional description, in the accent, success,
// warning or danger color.
//
//	alert.Alert(c, alert.Props{
//		Title:       "Heads up!",
//		Description: "You can add components to your app.",
//		Variant:     alert.Info,
//	})
package alert

import "github.com/egoist/mygo/ui"

// Variant is the color of an alert.
type Variant int

const (
	// Info is the default notice, in the accent color.
	Info Variant = iota
	// Success announces success, in the success color.
	Success
	// Warning announces a warning, in the warning color.
	Warning
	// Danger announces a failure, in the danger color.
	Danger
)

// Props describes the alert to draw.
type Props struct {
	// Title is the bold heading of the alert.
	Title string
	// Description is the text under the title.
	Description string
	// Variant is the color of the alert; Info unless set.
	Variant Variant
}

// Alert draws a rounded notice: a tinted face, a colored border and a
// colored bold title. It returns the notice, so a view can size it.
func Alert(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	col := variantColor(t, p.Variant)
	e := ui.Column(c).Radius(t.Radius).Clip().Padding(t.Space(3)).Gap(t.Space(1)).
		Background(ui.RGBA(col.R, col.G, col.B, 0.1)).
		Border(1, ui.RGBA(col.R, col.G, col.B, 0.4))
	e.Children(func() {
		if p.Title != "" {
			ui.Text(c, p.Title).Bold().TextColor(col)
		}
		if p.Description != "" {
			ui.Text(c, p.Description).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
		}
	})
	return e
}

// variantColor returns the color of a variant: the accent for Info.
func variantColor(t *ui.Theme, v Variant) ui.Color {
	switch v {
	case Success:
		return t.Success
	case Warning:
		return t.Warning
	case Danger:
		return t.Danger
	}
	return t.Accent
}

// Package appshell provides the AppShell of BoardUI for the MyGo native
// toolkit: the page frame of a starter, with the sidebar, the breadcrumb
// trail, the page heading and its actions, and the content below.
//
//	appshell.AppShell(c, appshell.Props{
//		Title:    "Dashboard",
//		Team:     "Board team",
//		Member:   "Mertcan",
//		Selected: &place,
//		Sections: sections,
//		Content:  func(c *ui.Context) { ... },
//	})
//
// The shell builds on the sidebar and breadcrumbs components; install
// them with it. It fills the window it is given, so a window can size
// it with Grow.
package appshell

import (
	"github.com/egoist/mygo/ui"

	"github.com/smallnest/uix/components/breadcrumbs"
	"github.com/smallnest/uix/components/sidebar"
)

// Props describes the shell to draw.
type Props struct {
	// Title is the page's name: the last breadcrumb item and the
	// default heading.
	Title string
	// Team and Member are the ancestors of the trail, such as the team
	// and the member of the app; empty ones are left out.
	Team, Member string
	// Heading is the big text over the content; the Title when empty.
	Heading string
	// Selected is the sidebar's choice, by item ID, as the sidebar
	// sets it.
	Selected *string
	// Sections are the sidebar's sections.
	Sections []sidebar.Section
	// Actions draw the header's buttons on the right; nil draws none.
	Actions func(c *ui.Context)
	// Content is the page below the header; nil draws nothing.
	Content func(c *ui.Context)
}

// AppShell draws the page frame and returns it, so a view can chain more
// calls on it.
func AppShell(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	return ui.Row(c).Fill().Gap(t.Space(4)).Padding(t.Space(3)).Children(func() {
		ui.Box(c).Width(260).FillHeight().Shrink(0).Background(t.Surface).
			Radius(t.Radius * 3).Padding(t.Space(2)).Children(func() {
			sidebar.Sidebar(c, sidebar.Props{
				Selected: p.Selected,
				Sections: p.Sections,
			})
		})
		ui.Column(c).Grow(1).MinWidth(0).FillHeight().Gap(t.Space(2.5)).
			Children(func() {
				breadcrumbRow(c, t, p)
				headingRow(c, t, p)
				if p.Content != nil {
					ui.Column(c).FillWidth().Grow(1).MinHeight(0).Gap(t.Space(4)).
						Children(func() {
							p.Content(c)
						})
				}
			})
	})
}

// breadcrumbRow is the trail to the page: the team, the member and the
// page, the last one where the path is.
func breadcrumbRow(c *ui.Context, t *ui.Theme, p Props) {
	var items []string
	if p.Team != "" {
		items = append(items, p.Team)
	}
	if p.Member != "" {
		items = append(items, p.Member)
	}
	items = append(items, p.Title)
	chosen := len(items) - 1
	breadcrumbs.Breadcrumbs(c, breadcrumbs.Props{Items: items, Chosen: &chosen})
}

// headingRow is the page heading on the left, with the actions on the
// right.
func headingRow(c *ui.Context, t *ui.Theme, p Props) {
	heading := p.Heading
	if heading == "" {
		heading = p.Title
	}
	ui.Row(c).FillWidth().Justify(ui.SpaceBetween).AlignItems(ui.Center).
		Gap(t.Space(4)).Children(func() {
		ui.Text(c, heading).FontSize(t.FontSize * 1.5).FontWeight(600).TextColor(t.Text)
		if p.Actions != nil {
			ui.Row(c).Gap(t.Space(2.5)).Children(func() { p.Actions(c) })
		}
	})
}

// Package autocomplete provides a field that completes the text as it is
// typed, as a shadcn/ui component for the Autocomplete of MyGo: the
// suggestions containing the text show below it, those starting with it
// first, and Up and Down move among them while Enter takes one.
//
//	autocomplete.Autocomplete(c, autocomplete.Props{
//		Value:       &task,
//		Suggestions: []string{"Water the plants", "Write the report"},
//		Label:       "Task",
//	})
package autocomplete

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the field to draw.
type Props struct {
	// Value is the text being edited, which the field changes in place,
	// as the user types or takes a suggestion.
	Value *string
	// Suggestions are the texts offered, of which those containing the
	// text show below the field, those starting with it first.
	Suggestions []string
	// Label names the field for the assistive technology.
	Label string
}

// Autocomplete draws the field and its suggestions below it, and returns
// it, so a view can chain more calls on it. The field stretches over its
// parent, as the other fields do; a bounded width overrides it in a Row.
func Autocomplete(c *ui.Context, p Props) *ui.Element {
	e := ui.Autocomplete(c, p.Value, p.Suggestions)
	e.FillWidth()
	if p.Label != "" {
		e.Label(p.Label)
	}
	return e
}

// Package avatar provides a shadcn/ui-style Avatar: a circle with a
// photo, or the initials of a name on a muted face. Assistive technology
// sees an image labeled with the name.
//
//	avatar.Avatar(c, avatar.Props{Name: "Ada Lovelace"})
package avatar

import (
	"unicode"

	"github.com/egoist/mygo/ui"
)

// Props describes the avatar to draw.
type Props struct {
	// Name is the person's name: its initials fill the circle when there
	// is no photo, and it labels the avatar for assistive technology.
	Name string
	// Image is the photo, cropped to the circle. Nil draws the initials.
	Image *ui.Bitmap
	// Size is the diameter of the circle, in points. 0 uses the default
	// of about twice the font size.
	Size float32
}

// Avatar draws a circle with the photo or the initials, and returns the
// circle.
func Avatar(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	size := p.Size
	if size == 0 {
		size = t.FontSize * 2.25
	}
	e := ui.Box(c).Size(size, size).Radius(size / 2).Clip().Shrink(0).Center().
		Role(ui.RoleImage).Label(p.Name)
	if p.Image != nil {
		e.Children(func() { ui.Image(c, p.Image).Fit(ui.Cover).Size(size, size) })
		return e
	}
	e.Background(t.SurfaceHover).TextColor(t.Text)
	e.Children(func() {
		ui.Text(c, initials(p.Name)).FontWeight(600).FontSize(size * 0.4).SingleLine()
	})
	return e
}

// initials returns the first letters of the first and last words of
// name, like "AL" for "Ada Lovelace". Why not MyGo's helper: it is
// unexported, and the loop is a few lines.
func initials(name string) string {
	var first, last rune
	inWord := false
	for _, r := range name {
		letter := unicode.IsLetter(r) || unicode.IsDigit(r)
		if letter && !inWord {
			if first == 0 {
				first = unicode.ToUpper(r)
			} else {
				last = unicode.ToUpper(r)
			}
		}
		inWord = letter
	}
	switch {
	case first == 0:
		return ""
	case last == 0:
		return string(first)
	}
	return string(first) + string(last)
}

// Package badge provides a shadcn/ui-style badge: a short label in a
// pill, for counts and status.
//
//	badge.Badge(c, badge.Props{Label: "Beta", Variant: badge.Secondary})
package badge

import "github.com/egoist/mygo/ui"

// Variant is the look of a badge.
type Variant int

const (
	// Default is a solid badge in the text color.
	Default Variant = iota
	// Secondary is a badge on a muted face.
	Secondary
	// Destructive is a badge in the danger color.
	Destructive
	// Outline is a bordered badge without a face.
	Outline
)

// Props describes the badge to draw.
type Props struct {
	// Label is the text of the badge.
	Label string
	// Variant is the look of the badge; Default unless set.
	Variant Variant
}

// Badge draws a pill with the label for props.
func Badge(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	face, fg, border := variantColors(t, p.Variant)
	b := ui.Box(c).Padding(t.Space(0.5), t.Space(1.5)).Radius(999).Background(face).TextColor(fg)
	if border.A > 0 {
		b.Border(1, border)
	}
	b.Children(func() { ui.Text(c, p.Label).SingleLine() })
	return b
}

// variantColors returns the face, text and border colors of a variant.
func variantColors(t *ui.Theme, v Variant) (face, fg, border ui.Color) {
	switch v {
	case Secondary:
		return t.SurfaceHover, t.Text, ui.Color{}
	case Destructive:
		return t.Danger, ui.Hex("#ffffff"), ui.Color{}
	case Outline:
		return ui.Color{}, t.Text, t.Border
	}
	// Default is the theme turned over: text on the text color, so it
	// reads in both appearances.
	return t.Text, t.InverseText, ui.Color{}
}

// Package barchart provides the OrdersChartCard of BoardUI for the MyGo
// native toolkit: a card of a year of monthly orders as paired bars, the
// current year against the year before. The current year's bars are the
// theme's accent, the year before's the muted gray behind them.
//
//	barchart.BarChart(c, barchart.Props{
//		Data:     months,
//		Selected: &active,
//		Title:    "Orders",
//	})
//
// Resting the pointer on a month swaps the headline for that month,
// shows its year-earlier figure, and puts a soft track behind the pair.
// The card fills the height it is given, so a dashboard row can size it
// with Grow.
package barchart

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"github.com/egoist/mygo/ui"
)

// Point is one month of the series.
type Point struct {
	// Label is the short month name, such as "Jan", on the axis.
	Label string
	// Current is the value of the current year.
	Current float64
	// Previous is the value of the year before.
	Previous float64
}

// Props describes the chart to draw.
type Props struct {
	// Data are the months, in order.
	Data []Point
	// Selected is the month under the pointer, by index, -1 for none.
	// The chart keeps it as the pointer moves over the plot and clears
	// it as the pointer leaves; pass nil to draw a chart that does not
	// follow the pointer.
	Selected *int
	// Title is the headline's label when no month is under the pointer.
	Title string
}

// months are the full names of the year, for the headline of the month
// under the pointer.
var months = []string{
	"January", "February", "March", "April", "May", "June",
	"July", "August", "September", "October", "November", "December",
}

// BarChart draws the card and returns it, so a view can chain more
// calls on it.
func BarChart(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	selected := -1
	if p.Selected != nil {
		selected = *p.Selected
	}
	title := p.Title
	if title == "" {
		title = "Orders"
	}
	label, current, previous, delta, up := headline(t, p.Data, selected, title)
	return ui.Column(c).Fill().Background(t.Surface).Radius(t.Radius * 2).
		Padding(t.Space(4), t.Space(4), t.Space(3), t.Space(4)).
		Gap(t.Space(4)).Children(func() {
		chartHeader(c, t, label, current, previous, delta, up)
		plot(c, t, p)
	})
}

// headline is what the header says: the total, or the month under the
// pointer and its year-earlier figure.
func headline(t *ui.Theme, data []Point, selected int, title string) (label, current, previous, delta string, up bool) {
	if selected >= 0 && selected < len(data) {
		pt := data[selected]
		label = pt.Label
		if len(pt.Label) >= 3 {
			if i := strings.Index("JanFebMarAprMayJunJulAugSepOctNovDec", pt.Label[:3]); i >= 0 {
				label = months[i/3]
			}
		}
		current, previous = grouped(int64(pt.Current)), grouped(int64(pt.Previous))
		delta, up = deltaOf(pt.Current, pt.Previous)
		return
	}
	var sumCur, sumPrev float64
	for _, pt := range data {
		sumCur += pt.Current
		sumPrev += pt.Previous
	}
	label = title
	current, previous = grouped(int64(sumCur)), grouped(int64(sumPrev))
	delta, up = deltaOf(sumCur, sumPrev)
	return
}

// chartHeader is the headline over the plot: the label, the value with
// its delta chip, the comparison under it, and the legend on the right.
func chartHeader(c *ui.Context, t *ui.Theme, label, current, previous, delta string, up bool) {
	ui.Row(c).FillWidth().Justify(ui.SpaceBetween).AlignItems(ui.Start).
		Gap(t.Space(3)).Children(func() {
		ui.Column(c).Gap(3).Children(func() {
			ui.Text(c, label).TextColor(t.TextMuted).SingleLine()
			ui.Row(c).AlignItems(ui.Center).Gap(t.Space(2)).Children(func() {
				ui.Text(c, current).FontSize(t.FontSize * 1.2).FontWeight(600).
					TextColor(t.Text).SingleLine()
				deltaChip(c, t, delta, up)
			})
			ui.Text(c, previous+" last year").FontSize(t.FontSize * 0.8).
				TextColor(t.TextMuted).SingleLine()
		})
		ui.Row(c).Gap(t.Space(4)).Children(func() {
			legend(c, t, t.Accent, "This year")
			legend(c, t, t.Text.Alpha(0.3), "Last year")
		})
	})
}

// legend is one named color dot.
func legend(c *ui.Context, t *ui.Theme, color ui.Color, name string) {
	ui.Row(c).Gap(t.Space(1)).AlignItems(ui.Center).Children(func() {
		ui.Box(c).Size(8, 8).Radius(4).Background(color)
		ui.Text(c, name).FontSize(t.FontSize * 0.8).TextColor(t.TextMuted).SingleLine()
	})
}

// plot is the chart itself: the grid, the bars, the hover track, and
// the invisible columns that feel the pointer.
func plot(c *ui.Context, t *ui.Theme, p Props) {
	plotBox := ui.Box(c).Grow(1).MinHeight(0)
	selected := -1
	if p.Selected != nil {
		hovered := -1
		// The invisible columns, one per month, tile the plot: the
		// pointer over one picks the month, over the margins clears it.
		plotBox.Children(func() {
			ui.Row(c).Fill().Padding(8, 8, 22, 40).Children(func() {
				for i := range p.Data {
					col := ui.Box(c).Grow(1).FillHeight()
					col.Label(p.Data[i].Label)
					if col.Hovered() {
						hovered = i
					}
				}
			})
		})
		if plotBox.Hovered() {
			*p.Selected = hovered
		} else {
			*p.Selected = -1
		}
		selected = *p.Selected
	}
	plotBox.Draw(func(pt *ui.Painter, r ui.Rect) {
		drawPlot(pt, t, p.Data, selected, r)
	})
}

// drawPlot paints the grid, the hover track, the paired bars and the
// month names, rounded like the BoardUI bars at their tops.
func drawPlot(pt *ui.Painter, t *ui.Theme, data []Point, selected int, r ui.Rect) {
	n := len(data)
	if n == 0 {
		return
	}
	plot := ui.Rect{X: r.X + 40, Y: r.Y + 8, W: r.W - 48, H: r.H - 30}
	var scale float64
	for _, p := range data {
		if m := math.Max(p.Current, p.Previous); m > scale {
			scale = m
		}
	}
	scale *= 1.1
	if scale == 0 {
		scale = 1
	}
	bottom := plot.Y + plot.H
	// The grid, four lines with their labels right-aligned on the left.
	for i := 0; i < 4; i++ {
		gy := plot.Y + plot.H*float32(i)/3
		pt.Line(plot.X, gy, plot.X+plot.W, gy, 1, t.Border)
		label := formatK(scale * float64(3-i) / 3)
		size := t.FontSize * 0.75
		w := float32(len(label)) * size * 0.55
		pt.Text(plot.X-8-w, gy+size*0.35, label, size, t.TextMuted)
	}
	// The month under the pointer, a soft track behind its pair.
	if selected >= 0 && selected < n {
		band := plot.W / float32(n)
		trackX := plot.X + band*float32(selected)
		pt.Fill(ui.Rect{X: trackX, Y: plot.Y, W: band, H: plot.H},
			t.Accent.Alpha(0.06), 0)
	}
	// The paired bars: the current year on the left of each pair, the
	// year before on the right, a gap between them.
	band := plot.W / float32(n)
	const barArea = 0.72
	const gap = 3
	barW := (band*barArea - gap) / 2
	for i, p := range data {
		x := plot.X + band*(float32(i)+0.5) - band*barArea/2
		hCur := (plot.H * float32(p.Current/scale))
		hPrev := (plot.H * float32(p.Previous/scale))
		topRounded(pt, x, bottom-hCur, barW, hCur, 4, t.Accent)
		topRounded(pt, x+barW+gap, bottom-hPrev, barW, hPrev, 4, t.Text.Alpha(0.3))
	}
	// The month names under the axis.
	size := t.FontSize * 0.75
	for i, p := range data {
		w := float32(len(p.Label)) * size * 0.55
		pt.Text(plot.X+band*(float32(i)+0.5)-w/2, plot.Y+plot.H+18, p.Label, size, t.TextMuted)
	}
}

// topRounded fills the rectangle with its top corners rounded, as the
// BoardUI bars rise from the axis.
func topRounded(pt *ui.Painter, x, y, w, h, r float32, c ui.Color) {
	if w <= 0 || h <= 0 {
		return
	}
	r = min(r, w/2, h)
	bottom := y + h
	var p ui.Path
	p.MoveTo(x, bottom)
	p.LineTo(x, y+r)
	p.QuadTo(x, y, x+r, y)
	p.LineTo(x+w-r, y)
	p.QuadTo(x+w, y, x+w, y+r)
	p.LineTo(x+w, bottom)
	p.Close()
	pt.FillPath(&p, c)
}

// deltaChip is the pill of the change, green for a gain, red for a
// loss, plain for a tie.
func deltaChip(c *ui.Context, t *ui.Theme, delta string, up bool) {
	flat := delta == "0%" || delta == "New"
	bg, fg := t.SurfaceHover, t.TextMuted
	if up {
		bg, fg = t.Success.Alpha(0.15), t.Success
	} else if !flat {
		bg, fg = t.Danger.Alpha(0.15), t.Danger
	}
	ui.Row(c).Shrink(0).Gap(3).Radius(9).Padding(2, 4).
		AlignItems(ui.Center).Background(bg).Children(func() {
		ui.Box(c).Size(12, 12).Draw(func(pt *ui.Painter, r ui.Rect) {
			cx, cy := r.X+r.W/2, r.Y+r.H/2
			if up {
				pt.Line(cx, cy+2.5, cx, cy-2.5, 1.6, fg)
				var p ui.Path
				p.MoveTo(cx-1.8, cy-0.5).LineTo(cx, cy-2.5).LineTo(cx+1.8, cy-0.5)
				pt.StrokePath(&p, 1.6, fg)
			} else if flat {
				pt.Line(cx-2.5, cy, cx+2.5, cy, 1.6, fg)
			} else {
				pt.Line(cx, cy-2.5, cx, cy+2.5, 1.6, fg)
				var p ui.Path
				p.MoveTo(cx-1.8, cy+0.5).LineTo(cx, cy+2.5).LineTo(cx+1.8, cy+0.5)
				pt.StrokePath(&p, 1.6, fg)
			}
		})
		ui.Text(c, delta).FontSize(t.FontSize * 0.8).TextColor(fg).SingleLine()
	})
}

// deltaOf is the change of current against previous: the label of the
// chip and whether it reads as a gain.
func deltaOf(current, previous float64) (label string, up bool) {
	if previous == 0 {
		return "New", false
	}
	change := (current - previous) / previous * 100
	rounded := math.Round(change*10) / 10
	if rounded == 0 {
		return "0%", false
	}
	if rounded > 0 {
		return fmt.Sprintf("+%s%%", strconv.FormatFloat(rounded, 'f', -1, 64)), true
	}
	return fmt.Sprintf("%s%%", strconv.FormatFloat(rounded, 'f', -1, 64)), false
}

// formatK is the axis label: "$14k" for the thousands, "$0" below.
func formatK(v float64) string {
	if v >= 1000 {
		return fmt.Sprintf("$%dk", int(math.Round(v/1000)))
	}
	return fmt.Sprintf("$%d", int(v))
}

// grouped writes n with a comma before every third digit.
func grouped(n int64) string {
	s := strconv.FormatInt(n, 10)
	start := len(s) % 3
	if start == 0 && len(s) > 3 {
		start = 3
	}
	var b strings.Builder
	for i, r := range s {
		if i > 0 && i == start {
			b.WriteByte(',')
		} else if i > start && (i-start)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}

// Package tokens provides the palette a uix app installs, the way the CSS
// variables of shadcn/ui give a web app its design tokens.
//
// The MyGo theme already names its colors semantically: Background,
// Surface, Text, Accent, Danger, Border and so on. This package curates
// their values into one palette. Apply it at the top of a view:
//
//	c.SetTheme(tokens.For(c.Theme().Dark))
//
// The mapping to the shadcn/ui tokens is:
//
//	background   -> Background    primary     -> Accent
//	foreground   -> Text          primary-fg  -> AccentText
//	secondary    -> Surface       destructive -> Danger
//	muted        -> SurfaceHover  border      -> Border
//	muted-fg     -> TextMuted     ring        -> Focus
//
// uix theme set regenerates this file from the palette it names.
package tokens

import "github.com/egoist/mygo/ui"

// Light returns the light appearance with the indigo palette. It
// starts from the MyGo light theme, which keeps the system-tuned
// neutrals, fonts and metrics, and overrides the values the palette
// names. Change a value here and every component restyles at once.
func Light() *ui.Theme {
	t := ui.LightTheme()
	t.Radius = 8
	t.Accent = ui.Hex("#6366f1")
	t.AccentHover = ui.Hex("#4f46e5")
	t.AccentPressed = ui.Hex("#4338ca")
	t.AccentText = ui.Hex("#ffffff")
	t.Danger = ui.Hex("#e11d48")
	t.Selection = ui.RGBA(99, 102, 241, 0.25)
	t.Focus = ui.RGBA(99, 102, 241, 0.55)
	return t
}

// Dark returns the dark appearance with the indigo palette.
func Dark() *ui.Theme {
	t := ui.DarkTheme()
	t.Radius = 8
	t.Accent = ui.Hex("#818cf8")
	t.AccentHover = ui.Hex("#6366f1")
	t.AccentPressed = ui.Hex("#4f46e5")
	t.AccentText = ui.Hex("#ffffff")
	t.Danger = ui.Hex("#f43f5e")
	t.Selection = ui.RGBA(129, 140, 248, 0.4)
	t.Focus = ui.RGBA(129, 140, 248, 0.6)
	return t
}

// For returns Light or Dark after the given appearance.
func For(dark bool) *ui.Theme {
	if dark {
		return Dark()
	}
	return Light()
}

// Package breadcrumbs provides a shadcn/ui-style Breadcrumb: a path of
// items separated by chevrons, as Finder's path bar shows one. The items
// but the last are links, which a click chooses, as Enter does, setting
// *Chosen to the index of the item clicked; the last item is where the
// path is, not a link. Long items shorten with an ellipsis as room runs
// short.
//
//	breadcrumbs.Breadcrumbs(c, breadcrumbs.Props{
//		Items:  []string{"Home", "Docs", "Guide"},
//		Chosen: &app.chosen,
//	})
package breadcrumbs

import "github.com/egoist/mygo/ui"

// Props describes the breadcrumb path to draw.
type Props struct {
	// Items are the items of the path, in order; the last is where the
	// path is.
	Items []string
	// Chosen is set to the index of the item a click chooses; -1 while
	// no item has been chosen.
	Chosen *int
	// Disabled keeps the items from being chosen.
	Disabled bool
}

// Breadcrumbs draws the path and returns it, so a view can chain more
// calls on it.
func Breadcrumbs(c *ui.Context, p Props) *ui.Element {
	e := ui.Breadcrumbs(c, p.Items, p.Chosen)
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package button provides a shadcn/ui-style Button for the MyGo native
// toolkit. It wraps the MyGo primitives in a variant and size system: a
// view asks for a button by its role, not by its colors.
//
//	button.Button(c, button.Props{
//		Label:   "Save",
//		Variant: button.Primary,
//		OnClick: save,
//	})
//
// All colors come from the theme of the Context, so applying the palette
// of the tokens package restyles every button in the app at once.
package button

import "github.com/egoist/mygo/ui"

// Variant is the role of a button: how it looks and what it does.
type Variant int

const (
	// Primary is the main action of a view, in the accent color.
	Primary Variant = iota
	// Secondary is a regular button on a surface.
	Secondary
	// Outline is a button with a border but no face.
	Outline
	// Ghost is a borderless button that fills on hover.
	Ghost
	// Destructive is for actions that cannot be undone, in the danger color.
	Destructive
	// Link is a text button styled as a link.
	Link
)

// Size sets how much room a button takes.
type Size int

const (
	// Sm is a compact button, for toolbars and tables.
	Sm Size = iota
	// Md is the default size.
	Md
	// Lg is a large button, for empty states and forms.
	Lg
)

// Props describes the button to draw.
type Props struct {
	// Label is the button's text.
	Label string
	// Variant is the role of the button; Primary by default.
	Variant Variant
	// Size is how large the button is; Md by default.
	Size Size
	// Disabled keeps the button from acting.
	Disabled bool
	// OnClick runs for the click, on the frame of the click.
	OnClick func()
}

// Button draws a button for props and returns the MyGo element behind it,
// so a view can chain more calls on it. When the user clicks, Button
// calls OnClick and the view rebuilds on the next frame.
func Button(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	switch p.Variant {
	case Link:
		return link(c, p)
	case Primary:
		b := ui.PrimaryButton(c, p.Label)
		paddingSize(c, t, b, p.Size, false)
		return finish(c, b, p)
	}
	// The variants with a custom face: Secondary, Outline, Ghost,
	// Destructive. The face is drawn each frame, so hover and press
	// track the pointer even though the view does not rebuild.
	face, hover, pressed, fg, border := variantColors(c, t, p.Variant)
	if p.Disabled {
		fg = t.TextMuted
	}
	b := ui.ButtonBase(c)
	paddingSize(c, t, b, p.Size, false)
	b.TextColor(fg)
	if border.A > 0 {
		b.Border(1, border)
	}
	radius := t.Radius
	b.Draw(func(pp *ui.Painter, r ui.Rect) {
		bg := face
		if !b.IsDisabled() {
			switch {
			case b.Pressed():
				bg = pressed
			case b.Hovered():
				bg = hover
			}
		}
		if bg.A > 0 {
			pp.Fill(r, bg, radius)
		}
	})
	b.Children(func() { ui.Text(c, p.Label).SingleLine() })
	return finish(c, b, p)
}

// variantColors returns the face, hover, pressed and text colors and the
// border color of a custom-face variant.
func variantColors(c *ui.Context, t *ui.Theme, v Variant) (face, hover, pressed, fg, border ui.Color) {
	switch v {
	case Secondary:
		return t.Surface, t.SurfaceHover, t.SurfacePressed, t.Text, t.Border
	case Outline:
		return ui.Color{}, ui.Color{}, ui.Color{}, t.Text, t.Border
	case Ghost:
		return ui.Color{}, t.SurfaceHover, t.SurfacePressed, t.Text, ui.Color{}
	case Destructive:
		return t.Danger, t.Danger, t.Danger, ui.Hex("#ffffff"), ui.Color{}
	}
	return ui.Color{}, ui.Color{}, ui.Color{}, t.Text, t.Border
}

// link draws a text button: accent text, no face, padded only across.
func link(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	b := ui.ButtonBase(c)
	fg := t.Accent
	if p.Disabled {
		fg = t.TextMuted
	}
	b.TextColor(fg)
	px := t.Space(3.5)
	if p.Size == Sm {
		px = t.Space(2.5)
	}
	if p.Size == Lg {
		px = t.Space(4.5)
	}
	b.PaddingX(px)
	b.Children(func() { ui.Text(c, p.Label).SingleLine() })
	return finish(c, b, p)
}

// paddingSize sets the padding of the button for its size.
func paddingSize(c *ui.Context, t *ui.Theme, b *ui.Element, s Size, link bool) {
	var py, px float32
	switch s {
	case Sm:
		py, px = t.Space(1), t.Space(2.5)
	case Lg:
		py, px = t.Space(2), t.Space(4.5)
	default:
		py, px = t.Space(1.5), t.Space(3.5)
	}
	if link {
		b.PaddingX(px)
	} else {
		b.Padding(py, px)
	}
}

// finish applies Disabled and runs OnClick for the click. Disabled is
// checked here so a disabled button never acts.
func finish(c *ui.Context, b *ui.Element, p Props) *ui.Element {
	if p.Disabled {
		b.Disabled(true)
	}
	if p.OnClick != nil && !p.Disabled && b.Clicked() {
		p.OnClick()
	}
	return b
}

// Package calendar provides a month's calendar choosing a day, as a
// shadcn/ui component for the Calendar of MyGo, like the graphical date
// picker of SwiftUI.
//
//	calendar.Calendar(c, calendar.Props{Date: &due})
package calendar

import (
	"time"

	"github.com/egoist/mygo/ui"
)

// Props describes the calendar to draw.
type Props struct {
	// Date is the day chosen, which the calendar changes in place,
	// keeping its time of day and its location.
	Date *time.Time
}

// Calendar draws the month around Date, and returns it, so a view can
// chain more calls on it. A click chooses a day, as the arrows do while
// the calendar has the focus, Page Up and Page Down move by months, and
// Home and End go to the first and the last day of the month.
func Calendar(c *ui.Context, p Props) *ui.Element {
	return ui.Calendar(c, p.Date)
}

// Package card provides a shadcn/ui-style Card: a bordered rounded
// container with an optional header and footer, for grouping related
// content on a surface.
//
//	card.Card(c, card.Props{
//		Title:       "Account",
//		Description: "How people reach you.",
//		Footer: func() {
//			button.Button(c, button.Props{Label: "Save", Variant: button.Primary})
//		},
//	}, func() {
//		field.Field(c, field.Props{Label: "Name"}, func() {
//			input.Input(c, input.Props{Value: &name})
//		})
//	})
package card

import "github.com/egoist/mygo/ui"

// Props describes the card to draw.
type Props struct {
	// Title is the heading of the card.
	Title string
	// Description is the text under the title.
	Description string
	// Footer draws into the action row at the bottom, right-aligned.
	Footer func()
}

// Card draws a bordered rounded container: the header, then the content
// that content draws, then the footer row. It returns the container, so
// a view can size it (for example, to grow in a column).
func Card(c *ui.Context, p Props, content func()) *ui.Element {
	t := c.Theme()
	return ui.Column(c).Background(t.Background).Border(1, t.Border).Radius(t.Radius).
		Padding(t.Space(4)).Gap(t.Space(3)).Children(func() {
		if p.Title != "" || p.Description != "" {
			ui.Column(c).Gap(t.Space(1)).Children(func() {
				if p.Title != "" {
					ui.Text(c, p.Title).Bold()
				}
				if p.Description != "" {
					ui.Text(c, p.Description).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
				}
			})
		}
		content()
		if p.Footer != nil {
			ui.Row(c).Justify(ui.End).Gap(t.Space(1.5)).Children(p.Footer)
		}
	})
}

// Package carousel provides the gallery carousel of BoardUI for the MyGo
// native toolkit: a horizontal run of slides you slide through with the
// previous and next buttons or the position dots, or with a trackpad.
//
//	carousel.Carousel(c, carousel.Props{
//		Count:  len(shots),
//		Slide: func(c *ui.Context, i int) { shots[i].Show(c) },
//		Scroll: &state.Scroll,
//		State:  &state.Carousel,
//	})
//
// The track is a horizontal scroll container, so the user scrolls it as
// a native app scrolls. Each slide is as wide as the track, one slide a
// view. The buttons sit above the track on the right and disable at the
// ends; the dots below tell which slide is showing and jump to the
// slide they name. The app keeps the ScrollState of the track and the
// State of the carousel, as it keeps the scroll of a chat.
package carousel

import (
	"fmt"

	"github.com/egoist/mygo/ui"
)

// Props describes the carousel to draw.
type Props struct {
	// Count is the number of slides.
	Count int
	// Slide builds slide i into the track; nil draws empty slides.
	Slide func(c *ui.Context, i int)
	// Scroll is the scroll state of the track, for the app to keep.
	// Without it the carousel draws but does not move.
	Scroll *ui.ScrollState
	// State is the carousel's own state, for the app to keep: which
	// slide is showing and whether either end is reached.
	State *State
	// HideArrows hides the previous and next buttons above the track.
	HideArrows bool
	// HideDots hides the position dots below the track.
	HideDots bool
	// Gap is the space between slides; 0 draws the theme's spacing.
	Gap float32
	// Height is the height of the track; the slides size it when 0.
	Height float32
}

// State is where the carousel is, kept by the app as the slides move.
type State struct {
	// Active is the slide showing, from 0.
	Active int
	// AtStart and AtEnd say whether either end of the track is reached.
	AtStart, AtEnd bool
	// viewport is how wide the track is, measured from its layout so the
	// slides can be as wide as the track a frame later.
	viewport float32
	// settling is true for one frame after the slide width changed, so
	// the width is not measured against the layout it has not had yet.
	settling bool
}

// Carousel draws the carousel and returns it, so a view can chain more
// calls on it.
func Carousel(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	n := max(1, p.Count)
	gap := p.Gap
	if gap == 0 {
		gap = t.Space(4)
	}
	// The width of a slide is the width of the track. A scroll row
	// measures its children with no bound on their width, so the width
	// must be in points, not percents: the track's width of the last
	// frame is read back from how far it can scroll, with the width of
	// the window for the very first frame.
	slideW := float32(0)
	measuring := p.Scroll != nil && p.State != nil && n > 1
	if measuring {
		st := p.State
		if st.viewport > 0 {
			slideW = st.viewport
		} else {
			w, _ := c.Size()
			slideW = w
			// A second frame, to measure the track once it is laid out.
			c.Invalidate()
		}
		if st.settling {
			// The layout has not yet seen the new slide width; measure
			// it a frame from now, when it has.
			st.settling = false
		} else if p.Scroll.MaxX > 0 {
			// The track shows slides and gaps, and can scroll the rest:
			// viewport = content - MaxX.
			v := float32(n)*slideW + float32(n-1)*gap - p.Scroll.MaxX
			if v != st.viewport {
				st.viewport = v
				st.settling = true
				c.Invalidate()
			}
		}
	}
	if p.Scroll != nil && p.State != nil {
		st := p.State
		if n > 1 && p.Scroll.MaxX > 0 {
			pitch := p.Scroll.MaxX / float32(n-1)
			st.Active = clamp(int((p.Scroll.X+pitch/2)/pitch), 0, n-1)
		} else {
			st.Active = 0
		}
		st.AtStart = p.Scroll.X <= 1
		st.AtEnd = p.Scroll.MaxX > 0 && p.Scroll.X >= p.Scroll.MaxX-1
	}
	return ui.Column(c).FillWidth().Gap(t.Space(4)).Children(func() {
		if !p.HideArrows && n > 1 {
			arrowRow(c, t, p, n)
		}
		scroll := ui.ScrollHorizontal(c).FillWidth().Gap(gap).TrackScroll(p.Scroll)
		if p.Height > 0 {
			scroll.Height(p.Height)
		}
		scroll.Children(func() {
			for i := 0; i < n; i++ {
				// The slide is as wide as the track and does not shrink,
				// so exactly one shows at a time.
				ui.Box(c).Width(slideW).Shrink(0).Children(func() {
					if p.Slide != nil {
						p.Slide(c, i)
					}
				})
			}
		})
		if !p.HideDots && n > 1 {
			dots(c, t, p, n)
		}
	})
}

// arrowRow is the previous and next buttons above the track on the
// right, as BoardUI draws them.
func arrowRow(c *ui.Context, t *ui.Theme, p Props, n int) {
	ui.Row(c).FillWidth().Justify(ui.End).Gap(t.Space(2)).Children(func() {
		arrow(c, t, p, "Previous slide", false, p.State.AtStart, n, p.State.Active-1)
		arrow(c, t, p, "Next slide", true, p.State.AtEnd, n, p.State.Active+1)
	})
}

// arrow is one of the previous and next buttons: a chevron in a round
// box, disabled at its end of the track.
func arrow(c *ui.Context, t *ui.Theme, p Props, label string, next bool, disabled bool, n, to int) {
	fg := t.Text
	if disabled {
		fg = t.TextMuted
	}
	b := ui.ButtonBase(c).Size(28, 28).Radius(t.Radius).Center()
	b.Label(label)
	b.Children(func() {
		ui.Box(c).Size(16, 16).Draw(func(pt *ui.Painter, r ui.Rect) {
			cx, cy := r.X+r.W/2, r.Y+r.H/2
			var p ui.Path
			if next {
				p.MoveTo(cx-3, cy-4).LineTo(cx+3, cy).LineTo(cx-3, cy+4)
			} else {
				p.MoveTo(cx+3, cy-4).LineTo(cx-3, cy).LineTo(cx+3, cy+4)
			}
			pt.StrokePath(&p, 1.8, fg)
		})
	})
	if disabled {
		b.Disabled(true)
	}
	if b.Clicked() {
		goTo(c, p, n, to)
	}
}

// dots is the position indicator below the track: a wide pill for the
// slide showing, small dots for the others, each jumping to its slide.
func dots(c *ui.Context, t *ui.Theme, p Props, n int) {
	ui.Row(c).FillWidth().Justify(ui.Center).Gap(6).Children(func() {
		for i := 0; i < n; i++ {
			active := p.State != nil && p.State.Active == i
			w := float32(6)
			bg := t.SurfaceHover
			if active {
				w, bg = 16, t.Text
			}
			dot := ui.ButtonBase(c).Width(w).Height(6).Radius(3).Background(bg)
			dot.Label(fmt.Sprintf("Go to slide %d", i+1))
			if dot.Clicked() {
				goTo(c, p, n, i)
			}
		}
	})
}

// goTo scrolls the track to slide i, keeping it within the slides.
func goTo(c *ui.Context, p Props, n, i int) {
	if p.Scroll == nil {
		return
	}
	i = clamp(i, 0, n-1)
	if n > 1 && p.Scroll.MaxX > 0 {
		p.Scroll.X = float32(i) * (p.Scroll.MaxX / float32(n-1))
	}
}

// clamp keeps i within [lo, hi].
func clamp(i, lo, hi int) int {
	if i < lo {
		return lo
	}
	if i > hi {
		return hi
	}
	return i
}

// Package chat provides a working chat surface for the MyGo native
// toolkit, built from the agent components: a transcript that scrolls,
// the thinking indicator while the model works, and the composer at the
// bottom. It is the AgentChat of BoardUI without the backend: the app
// owns the messages and sends them however it likes.
//
//	chat.Chat(c, chat.Props{
//		Messages: msgs,
//		Value:    &input,
//		Busy:     busy,
//		OnSubmit: send,
//	})
//
// The surface is a rounded card on the theme's Surface, one step darker
// than the window, with the composer's pill on the Background over it.
// A chat spans the width it is given and grows to the height it is
// given, so a window can size it with Grow.
package chat

import (
	"math"
	"time"

	"github.com/egoist/mygo/ui"

	"github.com/smallnest/uix/components/composer"
	"github.com/smallnest/uix/components/thinking"
)

// Role is who a message speaks for.
type Role int

const (
	// User is the person at the keyboard; their words go in a bubble.
	User Role = iota
	// Assistant is the model; its words read plain on the surface.
	Assistant
)

// Message is one line of the transcript.
type Message struct {
	// Role is who speaks.
	Role Role
	// Text is what they said. The assistant's message the model is
	// still writing grows as the app appends to it.
	Text string
	// Streaming marks the assistant's message as the one being written,
	// which draws a blinking caret after the text.
	Streaming bool
}

// Props describes the chat to draw.
type Props struct {
	// Messages are the lines of the transcript, oldest first. While the
	// model works the app keeps an empty assistant message at the end
	// and sets Thinking.
	Messages []Message
	// Value is the text being typed in the composer.
	Value *string
	// Busy keeps the composer's send a stop button.
	Busy bool
	// Thinking shows the thinking indicator where the reply will land;
	// set while the model works and nothing has been written yet.
	Thinking bool
	// OnSubmit runs when the composer sends, with the text as typed.
	OnSubmit func(text string)
	// OnStop runs when the stop button is clicked while Busy.
	OnStop func()
	// Model and Provider feed the composer's chip and status row.
	Model    string
	Provider string
	// Suggestions are the chips of the empty state, each sending itself.
	Suggestions []string
	// Scroll keeps the transcript's place, as TrackScroll does. Pass
	// one you keep, and the transcript follows the end when it is
	// already there. Nil scrolls without keeping the place.
	Scroll *ui.ScrollState
}

// Chat draws the chat surface and returns it, so a view can chain more
// calls on it.
func Chat(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	return ui.Column(c).Fill().Background(t.Surface).Radius(t.Radius * 3).Clip().
		Children(func() {
			if len(p.Messages) == 0 {
				empty(c, t, p)
			} else {
				transcript(c, t, p)
			}
			composerWrap(c, t, p)
		})
}

// transcript is the scrollable column of messages, with the thinking
// indicator where a reply will land.
func transcript(c *ui.Context, t *ui.Theme, p Props) {
	sc := ui.Scroll(c).Grow(1).MinHeight(0)
	if p.Scroll != nil {
		sc.TrackScroll(p.Scroll)
		// A log that follows its end, unless the user scrolled up from
		// it, as MyGo's Scroll describes.
		if p.Scroll.Y >= p.Scroll.MaxY-t.Space(2) && p.Scroll.MaxY > 0 {
			p.Scroll.Y = math.MaxFloat32
		}
	}
	sc.Children(func() {
		ui.Column(c).FillWidth().Gap(t.Space(5)).
			Padding(t.Space(6), t.Space(4), t.Space(2), t.Space(4)).
			Children(func() {
				for _, m := range p.Messages {
					message(c, t, m)
				}
				if p.Thinking {
					ui.Row(c).Padding(0, t.Space(1)).Children(func() {
						thinking.Thinking(c, thinking.Props{
							Label:   "Thinking",
							Variant: thinking.Wave,
						})
					})
				}
			})
	})
}

// empty is the centered prompt and suggestion chips of a new thread.
func empty(c *ui.Context, t *ui.Theme, p Props) {
	ui.Column(c).Grow(1).FillWidth().Center().Gap(t.Space(4)).
		Padding(0, t.Space(4)).Children(func() {
			ui.Column(c).Center().Gap(t.Space(1)).Children(func() {
				ui.Text(c, "What can I help with?").
					FontSize(t.FontSize * 1.4).FontWeight(600).TextColor(t.Text)
				ui.Text(c, "The chat runs against your own model key. "+
					"History stays in this app.").
					TextColor(t.TextMuted).TextAlign(ui.Center)
			})
			if len(p.Suggestions) > 0 {
				ui.Row(c).Wrap().Justify(ui.Center).Gap(t.Space(2)).Children(func() {
					for _, s := range p.Suggestions {
						chip(c, t, p, s)
					}
				})
			}
			if p.Thinking {
				ui.Row(c).Children(func() {
					thinking.Thinking(c, thinking.Props{
						Label:   "Thinking",
						Variant: thinking.Wave,
					})
				})
			}
		})
}

// chip is one suggestion, a pill that sends itself when clicked.
func chip(c *ui.Context, t *ui.Theme, p Props, s string) {
	b := ui.ButtonBase(c).Radius(t.Radius + 12).Background(t.Background).
		Padding(t.Space(2), t.Space(3.5))
	if b.Clicked() && p.OnSubmit != nil {
		p.OnSubmit(s)
	}
	b.Children(func() {
		ui.Text(c, s).TextColor(t.TextMuted).SingleLine()
	})
}

// message draws one line of the transcript, in its role's own voice.
func message(c *ui.Context, t *ui.Theme, m Message) {
	switch m.Role {
	case User:
		ui.Row(c).FillWidth().Justify(ui.End).Children(func() {
			ui.Box(c).MaxWidthPercent(75).Padding(t.Space(2.5), t.Space(3.5)).
				Radius(t.Radius + 4).Background(t.Accent).Children(func() {
				ui.Text(c, m.Text).TextColor(t.AccentText)
			})
		})
	default:
		ui.Row(c).FillWidth().Justify(ui.Start).AlignItems(ui.End).
			Gap(t.Space(1)).Children(func() {
				ui.Text(c, m.Text).MaxWidthPercent(85).TextColor(t.Text)
				if m.Streaming {
					caret(c, t)
				}
			})
	}
}

// caret is the blinking block that marks the line the model is writing.
func caret(c *ui.Context, t *ui.Theme) *ui.Element {
	size := t.FontSize
	return ui.Box(c).Size(2, size).Shrink(0).Draw(func(pt *ui.Painter, r ui.Rect) {
		phase := float64(pt.Now().UnixMilli()%800) / 800
		// A triangle wave of opacity: fade out then snap back, as a
		// caret does.
		a := float32(math.Abs(1 - 2*phase))
		pt.Fill(ui.Rect{X: r.X, Y: r.Y, W: r.W, H: r.H}, t.Text.Alpha(a), 1)
		pt.After(80 * time.Millisecond)
	})
}

// composerWrap is the composer with the room it keeps from the edge of
// the card.
func composerWrap(c *ui.Context, t *ui.Theme, p Props) {
	ui.Column(c).Padding(0, t.Space(3)).Shrink(0).Children(func() {
		composer.Composer(c, composer.Props{
			Value:        p.Value,
			Busy:         p.Busy,
			OnSubmit:     p.OnSubmit,
			OnStop:       p.OnStop,
			Model:        p.Model,
			Provider:     p.Provider,
			MessageCount: len(p.Messages),
		})
	})
}

