// Package dialog provides a shadcn/ui-style modal dialog with a title, a
// description and an action row, on top of the DialogBase of MyGo.
//
//	dialog.Dialog(c, dialog.Props{
//		Open:        &open,
//		Title:       "Delete account?",
//		Description: "This cannot be undone.",
//		Confirm:     "Delete",
//		Destructive: true,
//		OnConfirm:   deleteAccount,
//	})
package dialog

import "github.com/egoist/mygo/ui"

// Props describes the dialog to draw.
type Props struct {
	// Open is the bool that shows and hides the dialog; the backdrop
	// and Escape set it to false.
	Open *bool
	// Title is the heading of the dialog.
	Title string
	// Description is the text under the title.
	Description string
	// Confirm labels the confirm button; an empty label hides it.
	Confirm string
	// Cancel labels the cancel button; "Cancel" when empty.
	Cancel string
	// Destructive colors the confirm button with the danger color.
	Destructive bool
	// OnConfirm runs for the confirm button, which also closes the
	// dialog.
	OnConfirm func()
	// OnCancel runs for the cancel button; the button closes the
	// dialog either way.
	OnCancel func()
}

// Dialog draws the dialog for props, or nothing while it is closed, and
// returns the panel. The backdrop dims the window; clicking it or
// pressing Escape closes the dialog.
func Dialog(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	cancel := p.Cancel
	if cancel == "" {
		cancel = "Cancel"
	}
	return ui.DialogBase(c, p.Open, func(back, panel *ui.Element) {
		back.Background(ui.RGBA(0, 0, 0, 0.4))
		panel.Padding(t.Space(5)).Gap(t.Space(3)).Radius(t.Radius+4).Background(t.Background).
			MinWidth(t.Space(48)).MaxWidth(t.Space(72)).Shadow(0, 10, 30, 0, ui.RGBA(0, 0, 0, 0.3))
		panel.Children(func() {
			ui.Column(c).Gap(t.Space(1.5)).Children(func() {
				ui.Text(c, p.Title).Bold()
				if p.Description != "" {
					ui.Text(c, p.Description).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
				}
			})
			ui.Row(c).Justify(ui.End).Gap(t.Space(1.5)).Children(func() {
				cancelButton(c, t, cancel, p)
				if p.Confirm != "" {
					confirmButton(c, t, p)
				}
			})
		})
	})
}

// cancelButton draws the cancel button, which closes the dialog. Why not
// a hover face: the pointer is already inside the modal, so a solid face
// keeps the dialog calm, as the Modal of MyGo does.
func cancelButton(c *ui.Context, t *ui.Theme, label string, p Props) {
	b := ui.ButtonBase(c).Padding(t.Space(1.5), t.Space(3.5)).Radius(t.Radius).
		Background(t.Surface).TextColor(t.Text).Border(1, t.Border)
	b.Children(func() { ui.Text(c, label).SingleLine() })
	if b.Clicked() {
		*p.Open = false
		if p.OnCancel != nil {
			p.OnCancel()
		}
	}
}

// confirmButton draws the confirm button, in the accent or the danger
// color, which closes the dialog and runs OnConfirm.
func confirmButton(c *ui.Context, t *ui.Theme, p Props) {
	face, fg := t.Accent, t.AccentText
	if p.Destructive {
		face, fg = t.Danger, ui.Hex("#ffffff")
	}
	b := ui.ButtonBase(c).Padding(t.Space(1.5), t.Space(3.5)).Radius(t.Radius).Background(face).TextColor(fg)
	b.Children(func() { ui.Text(c, p.Confirm).SingleLine() })
	if b.Clicked() {
		*p.Open = false
		if p.OnConfirm != nil {
			p.OnConfirm()
		}
	}
}

// Package dropdown provides a shadcn/ui-style dropdown menu: a button
// that opens a list of actions under it, to run one. The menu is a panel
// styled like a select's popup, over the view; it closes on a choice, on
// a press outside the menu or the button, or on Escape.
//
//	dropdown.Dropdown(c, dropdown.Props{
//		Trigger: "Account",
//		Open:    &open,
//		Items: []dropdown.Item{
//			{Label: "View profile", OnClick: viewProfile},
//			{Label: "Copy link", OnClick: copyLink},
//			{Separator: true},
//			{Label: "Sign out", OnClick: signOut},
//		},
//	})
package dropdown

import "github.com/egoist/mygo/ui"

// Item is one entry of a dropdown menu.
type Item struct {
	// Label is the text of the item.
	Label string
	// Disabled keeps the item from acting; it still shows, muted.
	Disabled bool
	// Separator draws a divider instead of a row; the other fields of a
	// separator are ignored.
	Separator bool
	// OnClick runs when the item is chosen; the menu closes either way.
	OnClick func()
}

// Props describes the dropdown to draw.
type Props struct {
	// Trigger is the label of the button that opens the menu.
	Trigger string
	// Open shows the menu while true; the button toggles it, and a
	// choice, a press outside the menu and the button, and Escape set
	// it to false.
	Open *bool
	// Items are the entries of the menu, in order.
	Items []Item
}

// Dropdown draws a button for props, with a menu of its items under it,
// and returns the button. The button opens the menu; choosing an item
// runs its OnClick and closes the menu. Why not a modal backdrop: a
// modal popover is not exposed by PopoverBase, and without one the press
// that closes the menu goes on to what is under it, as with the web's
// dropdown menus.
func Dropdown(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	b := ui.ButtonBase(c).Padding(t.Space(1.5), t.Space(3.5)).Radius(t.Radius).
		Background(t.Surface).TextColor(t.Text).Border(1, t.Border)
	b.Children(func() {
		ui.Row(c).Gap(t.Space(1.5)).Children(func() {
			ui.Text(c, p.Trigger).SingleLine()
			chevron(c, t)
		})
	})
	// The button toggles the menu. Why not a popover that closes on a
	// press of the button: the popover leaves the presses on its anchor
	// to the anchor, so the toggle is the whole story of the button, and
	// the presses elsewhere are the popover's to close.
	if b.Clicked() {
		*p.Open = !*p.Open
	}
	ui.PopoverBase(c, b, p.Open, func(panel *ui.Element) {
		panel.Margin(t.Space(1), 0, 0, 0).Padding(t.Space(1)).Radius(t.Radius+2).
			Background(t.Background).Border(1, t.Border).MinWidth(t.Space(36))
		panel.Shadow(0, 6, 20, 0, ui.RGBA(0, 0, 0, 0.18))
		panel.Children(func() {
			for _, it := range p.Items {
				item(c, t, it, p.Open)
			}
		})
	})
	return b
}

// item draws one entry of the menu: a divider for a separator, else a
// row that runs its OnClick and closes the menu.
func item(c *ui.Context, t *ui.Theme, it Item, open *bool) {
	if it.Separator {
		ui.Box(c).FillWidth().Height(1).Margin(t.Space(0.5), 0, t.Space(0.5), 0).Background(t.Border)
		return
	}
	row := ui.ButtonBase(c).FillWidth().Padding(t.Space(1.25), t.Space(2.5)).Radius(t.Radius)
	fg := t.Text
	if it.Disabled {
		fg = t.TextMuted
	}
	row.TextColor(fg)
	if !it.Disabled {
		row.Draw(func(p *ui.Painter, r ui.Rect) {
			if row.Hovered() {
				p.Fill(r, t.SurfaceHover, t.Radius)
			}
		})
	}
	row.Children(func() { ui.Text(c, it.Label).SingleLine() })
	if row.Clicked() && !it.Disabled {
		*open = false
		if it.OnClick != nil {
			it.OnClick()
		}
	}
}

// chevron draws the arrow of the button.
func chevron(c *ui.Context, t *ui.Theme) {
	ui.Box(c).Size(t.Space(2.5), t.Space(2.5)).Shrink(0).Draw(func(p *ui.Painter, r ui.Rect) {
		var path ui.Path
		path.MoveTo(r.X+r.W*0.1, r.Y+r.H*0.3).LineTo(r.X+r.W*0.5, r.Y+r.H*0.7).LineTo(r.X+r.W*0.9, r.Y+r.H*0.3)
		p.StrokePath(&path, 1.5, t.TextMuted)
	})
}

// Package editabletext provides a text the user edits in place, as a
// shadcn/ui component for the EditableText of MyGo: a double click on
// it, or Enter while it has the focus, shows a field of it, with the
// text before the extension chosen, ready to type over.
//
//	editabletext.EditableText(c, editabletext.Props{
//		Value:    &title,
//		OnChange: func(v string) { app.rename(v) },
//	})
package editabletext

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the editable text to draw.
type Props struct {
	// Value is the text shown and edited.
	Value *string
	// OnChange runs when the user commits a new text, by Enter or by
	// moving the focus away.
	OnChange func(v string)
}

// EditableText draws the value as a text the user edits in place, and
// returns it. A double click on it, or Enter while it has the focus,
// shows a field with the text before its extension chosen; Enter or
// moving the focus away keeps what was typed, and Escape goes back.
func EditableText(c *ui.Context, p Props) *ui.Element {
	e := ui.EditableText(c, p.Value)
	if e.Changed() && p.OnChange != nil {
		p.OnChange(*p.Value)
	}
	return e
}

// Package field wraps a form control with its label and helper text, as
// the FormItem of shadcn/ui does. A field is a small column:
//
//	field.Field(c, field.Props{
//		Label: "Name",
//		Hint:  "How people find you.",
//	}, func() {
//		input.Input(c, input.Props{Value: &name})
//	})
//
// The label and the messages come from the theme, so the palette of the
// tokens package restyles every field at once.
package field

import "github.com/egoist/mygo/ui"

// Props describes the field to draw.
type Props struct {
	// Label is the name of the control.
	Label string
	// Required marks the field as mandatory, with a star.
	Required bool
	// Hint is the helper text under the control.
	Hint string
	// Error is the validation message under the control. It replaces
	// Hint and shows in the danger color.
	Error string
}

// Field draws the label, the control that fn builds, and the message
// under it, and returns the column.
func Field(c *ui.Context, p Props, fn func()) *ui.Element {
	t := c.Theme()
	return ui.Column(c).Gap(t.Space(0.5)).Children(func() {
		if p.Label != "" {
			// A required label ends in a star in the danger color.
			ui.Row(c).Gap(t.Space(0.5)).Children(func() {
				ui.Text(c, p.Label).FontSize(t.FontSize * 0.875).Bold().TextColor(t.TextMuted)
				if p.Required {
					ui.Text(c, "*").FontSize(t.FontSize * 0.875).Bold().TextColor(t.Danger)
				}
			})
		}
		fn()
		switch {
		case p.Error != "":
			ui.Text(c, p.Error).FontSize(t.FontSize * 0.875).TextColor(t.Danger)
		case p.Hint != "":
			ui.Text(c, p.Hint).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
		}
	})
}

// Package fieldset provides a group of fields under a legend, as a
// shadcn/ui component for the Fieldset of MyGo.
//
//	fieldset.Fieldset(c, fieldset.Props{
//		Legend: "Type",
//		Children: func(c *ui.Context) {
//			radio.Radio(c, radio.Props{...})
//		},
//	})
package fieldset

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the field set to draw.
type Props struct {
	// Legend is the bold text above the fields.
	Legend string
	// Children are the fields of the group.
	Children func(c *ui.Context)
}

// Fieldset draws the legend and the fields as a group, and returns the
// column. A margin sits above it when another group is above it.
func Fieldset(c *ui.Context, p Props) *ui.Element {
	return ui.Fieldset(c, p.Legend, func() {
		if p.Children != nil {
			p.Children(c)
		}
	})
}

// Package fileupload provides the file upload of BoardUI for the MyGo
// native toolkit: a drop zone you click to pick a file, which then
// uploads with a progress ring and a percentage until it is done.
//
//	fileupload.FileUpload(c, fileupload.Props{
//		State: &state.Upload,
//	})
//
// The zone names the accepted kinds and the size limit, picks a file
// through the native open dialog, rejects files outside them with the
// reason, and simulates the upload, so the component needs no storage
// layer: connect OnComplete to your upload/storage layer. The app owns
// the State, as it owns the scroll of a chat. Drag and drop of BoardUI
// has no native file counterpart in MyGo, so the zone selects with a
// click instead; Pick can replace the dialog with any picker.
package fileupload

import (
	"fmt"
	"math"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/egoist/mygo"
	"github.com/egoist/mygo/ui"
)

// Phase is where the upload is.
type Phase int

// The phases of the zone.
const (
	// Idle invites a file.
	Idle Phase = iota
	// Uploading shows the file and its progress.
	Uploading
	// Complete announces the finished upload before returning to Idle.
	Complete
)

// The timings of the simulated upload. Tests shorten them to run the
// simulation in a few frames.
var (
	// UploadDuration is how long a simulated upload takes.
	UploadDuration = 2200 * time.Millisecond
	// CompleteHold is how long the complete state shows before it resets.
	CompleteHold = 1600 * time.Millisecond
	// RejectionHold is how long a rejection message shows.
	RejectionHold = 2600 * time.Millisecond
	// progressTick is how often the ring repaints while uploading.
	progressTick = 100 * time.Millisecond
)

// State is where the upload is, kept by the app.
type State struct {
	// Phase of the zone.
	Phase Phase
	// Name and Size of the file uploading or uploaded.
	Name string
	Size int64
	// Progress is the upload in percent, 0 to 100.
	Progress int
	// Rejection is why the last file was not accepted, "" when none.
	Rejection string

	// started is when the upload began, next when it moves on, and
	// rejectionUntil when the rejection clears; the simulation reads
	// them as time passes.
	started        time.Time
	next           time.Time
	rejectionUntil time.Time
}

// Start begins the simulated upload of a valid file at the time now, as
// picking it would: pass time.Now to start now, or an earlier time to
// show progress already made. Examples and tests use it without a
// dialog.
func (s *State) Start(name string, size int64, now time.Time) {
	s.Phase = Uploading
	s.Name = name
	s.Size = size
	s.Progress = 0
	s.Rejection = ""
	s.started = now
	s.next = time.Time{}
}

// Picked is a file the picker chose.
type Picked struct {
	Name string
	Size int64
}

// Props describes the upload zone to draw.
type Props struct {
	// State is where the upload is, for the app to keep.
	State *State
	// Pick chooses a file when the zone is clicked; nil opens the native
	// dialog filtered to the allowed kinds.
	Pick func() (Picked, error)
	// AllowedExtensions are the accepted file extensions without dots;
	// pdf, jpg, jpeg, png and xlsx when nil.
	AllowedExtensions []string
	// MaxBytes is the largest accepted file; 8 MB when zero.
	MaxBytes int64
	// Height is the height of the zone; 164 when zero.
	Height float32
	// OnComplete reports the file when the simulated upload finishes.
	OnComplete func(name string, size int64)
}

// The kinds and the limit BoardUI accepts.
var defaultExtensions = []string{"pdf", "jpg", "jpeg", "png", "xlsx"}

const defaultMaxBytes int64 = 8 << 20

// FileUpload draws the upload zone and returns it, so a view can chain
// more calls on it.
func FileUpload(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	st := p.State
	if st == nil {
		st = &State{}
	}
	exts := p.AllowedExtensions
	if len(exts) == 0 {
		exts = defaultExtensions
	}
	maxBytes := p.MaxBytes
	if maxBytes <= 0 {
		maxBytes = defaultMaxBytes
	}
	h := p.Height
	if h <= 0 {
		h = 164
	}
	radius := t.Radius * 2

	// The simulation advances with the clock, so the ring moves whether
	// or not the view changes otherwise.
	tick(c, st, p)

	z := ui.ButtonBase(c).FillWidth().Height(h).Radius(radius).Background(t.Surface)
	z.Label("Upload a file")
	if st.Phase != Idle {
		z.Disabled(true)
		// The ring around the zone and the percent badge above its middle,
		// drawn each frame as the progress advances.
		z.Draw(func(pt *ui.Painter, r ui.Rect) {
			ring := ui.Rect{X: r.X + 1, Y: r.Y + 1, W: r.W - 2, H: r.H - 2}
			pt.Stroke(ring, t.Border, radius, 2)
			frac := float32(st.Progress) / 100
			if frac > 0 {
				pt.StrokePath(ringPath(ring, radius, frac), 2, t.Accent)
			}
			badge := fmt.Sprintf("%d%%", st.Progress)
			size := t.FontSize * 0.8
			w := float32(len(badge))*size*0.55 + 12
			br := ui.Rect{X: r.X + r.W/2 - w/2, Y: r.Y + 8, W: w, H: 18}
			pt.Fill(br, t.Accent, 9)
			tw := float32(len(badge)) * size * 0.55
			pt.Text(br.X+(br.W-tw)/2, br.Y+br.H/2+size*0.35, badge, size, t.AccentText)
		})
	} else {
		// The dashed outline of the invite, darker while the pointer
		// rests on the zone.
		z.Draw(func(pt *ui.Painter, r ui.Rect) {
			dash := t.Border
			if z.Hovered() {
				dash = t.Text.Alpha(0.35)
			}
			pt.StrokeDashed(ui.Rect{X: r.X + 1, Y: r.Y + 1, W: r.W - 2, H: r.H - 2}, dash, radius, 2)
		})
	}
	z.Children(func() {
		ui.Column(c).FillWidth().Children(func() {
			if st.Phase == Idle {
				idle(c, t, st, exts, maxBytes)
			} else {
				busy(c, t, st)
			}
		})
	})
	if st.Phase == Idle && z.Clicked() {
		pick := p.Pick
		if pick == nil {
			pick = defaultPick(exts)
		}
		if f, err := pick(); err == nil && f.Name != "" {
			startUpload(st, c.Now(), f, exts, maxBytes)
		}
	}
	return z
}

// idle is the invite: the cloud icon, the tagline, and the kinds with
// the size limit, or the rejection instead of the tagline.
func idle(c *ui.Context, t *ui.Theme, st *State, exts []string, maxBytes int64) {
	ui.Column(c).FillWidth().Grow(1).Center().Gap(t.Space(1.5)).Children(func() {
		ui.Box(c).Size(40, 40).Background(t.SurfaceHover).Radius(20).Center().Children(func() {
			cloudIcon(c, t)
		})
		if st.Rejection == "" {
			ui.Row(c).Center().Gap(2).Children(func() {
				ui.Text(c, "Drag and drop to upload or ").TextColor(t.TextMuted).SingleLine()
				ui.Text(c, "select").TextColor(t.Accent).SingleLine()
			})
		} else {
			ui.Text(c, st.Rejection).TextColor(t.Danger).SingleLine()
		}
		ui.Text(c, fmt.Sprintf("%s (max %s)", allowedLabel(exts), formatFileSize(maxBytes))).
			FontSize(t.FontSize * 0.85).TextColor(t.TextMuted.Alpha(0.7)).SingleLine()
	})
}

// busy is the upload: the file icon, its name, and the line that moves
// from uploading to done.
func busy(c *ui.Context, t *ui.Theme, st *State) {
	ui.Column(c).FillWidth().Grow(1).Center().Gap(t.Space(1)).Children(func() {
		ui.Box(c).Size(40, 40).Radius(20).Border(1, t.Border).Center().Children(func() {
			fileIcon(c, t, t.Text)
		})
		ui.Text(c, st.Name).TextColor(t.Text).SingleLine()
		if st.Phase == Uploading {
			ui.Text(c, fmt.Sprintf("Uploading %s…", formatFileSize(st.Size))).TextColor(t.TextMuted).SingleLine()
		} else {
			ui.Text(c, "Uploaded successfully!").TextColor(t.Success).SingleLine()
		}
	})
}

// tick advances the simulation: the progress with the clock while
// uploading, the return to idle after the complete hold, and the
// clearing of a rejection. It asks for the frames those take.
func tick(c *ui.Context, st *State, p Props) {
	now := c.Now()
	switch st.Phase {
	case Uploading:
		elapsed := now.Sub(st.started)
		st.Progress = int(float64(elapsed) * 100 / float64(UploadDuration))
		if st.Progress >= 100 {
			st.Progress = 100
			st.Phase = Complete
			st.next = now.Add(CompleteHold)
			c.After(CompleteHold)
			return
		}
		// A frame in a tick keeps the ring moving; the completion timer
		// wakes it at the end.
		c.After(progressTick)
		c.After(UploadDuration - elapsed)
	case Complete:
		if st.next.IsZero() {
			// Set only now, so a preset complete state holds from here.
			st.next = now.Add(CompleteHold)
			c.After(CompleteHold)
			return
		}
		if now.Before(st.next) {
			c.After(st.next.Sub(now))
			return
		}
		if p.OnComplete != nil {
			p.OnComplete(st.Name, st.Size)
		}
		st.Phase = Idle
		st.Name, st.Size, st.Progress = "", 0, 0
	}
	if st.Rejection != "" {
		if now.Before(st.rejectionUntil) {
			c.After(st.rejectionUntil.Sub(now))
		} else {
			st.Rejection = ""
		}
	}
}

// startUpload validates the picked file and begins its upload, or
// rejects it with the reason, as BoardUI does.
func startUpload(st *State, now time.Time, f Picked, exts []string, maxBytes int64) {
	if !accepted(f.Name, exts) {
		st.Rejection = fmt.Sprintf("Only %s files are supported", upperAll(exts))
		st.rejectionUntil = now.Add(RejectionHold)
		return
	}
	if f.Size > maxBytes {
		st.Rejection = fmt.Sprintf("That file is larger than %s", formatFileSize(maxBytes))
		st.rejectionUntil = now.Add(RejectionHold)
		return
	}
	st.Start(f.Name, f.Size, now)
}

// defaultPick is the native open dialog, filtered to the allowed kinds.
func defaultPick(exts []string) func() (Picked, error) {
	return func() (Picked, error) {
		paths, err := mygo.Dialog.Open(mygo.OpenDialogOptions{
			Title:       "Upload a file",
			ButtonLabel: "Upload",
			Filters:     []mygo.FileFilter{{Name: "Supported files", Extensions: exts}},
		})
		if err != nil || len(paths) == 0 {
			return Picked{}, err
		}
		st, err := os.Stat(paths[0])
		if err != nil {
			return Picked{}, err
		}
		return Picked{Name: filepath.Base(paths[0]), Size: st.Size()}, nil
	}
}

// accepted reports whether the file's extension is among the kinds.
func accepted(name string, exts []string) bool {
	e := strings.ToLower(extensionFor(name))
	for _, x := range exts {
		if strings.ToLower(x) == e {
			return true
		}
	}
	return false
}

// extensionFor is the suffix after the last dot, "" without one.
func extensionFor(name string) string {
	if i := strings.LastIndexByte(name, '.'); i >= 0 {
		return name[i+1:]
	}
	return ""
}

// allowedLabel is the kinds the tagline names, without the duplicate
// jpeg, as BoardUI names them.
func allowedLabel(exts []string) string {
	var kept []string
	for _, e := range exts {
		if e != "jpeg" {
			kept = append(kept, strings.ToUpper(e))
		}
	}
	return strings.Join(kept, ", ")
}

// upperAll is the kinds a rejection names.
func upperAll(exts []string) string {
	up := make([]string, len(exts))
	for i, e := range exts {
		up[i] = strings.ToUpper(e)
	}
	return strings.Join(up, ", ")
}

// formatFileSize names a size in bytes the way BoardUI does: whole MB
// from ten up, one decimal below, whole KB below a MB and at least one.
func formatFileSize(bytes int64) string {
	if bytes >= 1024*1024 {
		mb := float64(bytes) / (1024 * 1024)
		if mb >= 10 {
			return fmt.Sprintf("%d MB", int64(math.Round(mb)))
		}
		// One decimal, and a whole number drops it, as BoardUI shows it.
		v := math.Round(mb*10) / 10
		if v == float64(int64(v)) {
			return fmt.Sprintf("%d MB", int64(v))
		}
		return fmt.Sprintf("%.1f MB", v)
	}
	return fmt.Sprintf("%d KB", max(1, bytes/1024))
}

// cloudIcon is the cloud with the up arrow of the invite, punched out
// of the cloud with the circle's color.
func cloudIcon(c *ui.Context, t *ui.Theme) {
	ui.Box(c).Size(24, 24).Draw(func(pt *ui.Painter, r ui.Rect) {
		cx, cy := r.X+r.W/2, r.Y+r.H/2
		fg := t.TextMuted
		hole := t.SurfaceHover
		// The cloud: a band under three bumps.
		pt.Fill(ui.Rect{X: cx - 11, Y: cy + 1, W: 22, H: 7}, fg, 3.5)
		for _, b := range []struct{ x, y, rad float32 }{
			{cx - 6.5, cy - 1, 4.5},
			{cx, cy - 3.5, 6},
			{cx + 6.5, cy - 1, 4.5},
		} {
			pt.Fill(ui.Rect{X: b.x - b.rad, Y: b.y - b.rad, W: 2 * b.rad, H: 2 * b.rad}, fg, b.rad)
		}
		// The up arrow, cut out of the cloud.
		pt.Fill(ui.Rect{X: cx - 1.5, Y: cy - 2, W: 3, H: 8}, hole, 1.5)
		var head ui.Path
		head.MoveTo(cx-5, cy-1).LineTo(cx, cy-7).LineTo(cx+5, cy-1).LineTo(cx+2.5, cy-1).
			LineTo(cx+2.5, cy+2).LineTo(cx-2.5, cy+2).LineTo(cx-2.5, cy-1).Close()
		pt.FillPath(&head, hole)
	})
}

// fileIcon is the document with the folded corner and two lines of the
// busy view, as a line icon.
func fileIcon(c *ui.Context, t *ui.Theme, fg ui.Color) {
	ui.Box(c).Size(24, 24).Draw(func(pt *ui.Painter, r ui.Rect) {
		cx, cy := r.X+r.W/2, r.Y+r.H/2
		var doc ui.Path
		doc.MoveTo(cx-9, cy-12).LineTo(cx+3, cy-12).LineTo(cx+10, cy-5).LineTo(cx+10, cy+12).
			LineTo(cx-9, cy+12).Close()
		pt.StrokePath(&doc, 1.8, fg)
		pt.Fill(ui.Rect{X: cx - 6, Y: cy - 1, W: 9, H: 2}, fg, 1)
		pt.Fill(ui.Rect{X: cx - 6, Y: cy + 4, W: 12, H: 2}, fg, 1)
	})
}

// ringPath is the perimeter of the rounded rectangle from the top
// center clockwise, up to the given fraction of it: the progress arc of
// the ring.
func ringPath(r ui.Rect, radius float32, frac float32) *ui.Path {
	radius = min(radius, r.W/2, r.H/2)
	x0, y0, x1, y1 := r.X, r.Y, r.X+r.W, r.Y+r.H
	type piece struct {
		length float32
		at     func(a float32) xy
	}
	arc := func(cx, cy, from, to float32) piece {
		return piece{math.Pi / 2 * radius, func(a float32) xy {
			ang := from + (to-from)*a
			return xy{cx + radius*float32(math.Cos(float64(ang))), cy + radius*float32(math.Sin(float64(ang)))}
		}}
	}
	// The eight pieces of the perimeter: the four straight edges and the
	// four quarter arcs at the corners.
	pieces := []piece{
		{r.W/2 - radius, func(a float32) xy { return xy{x0 + r.W/2 + (r.W/2-radius)*a, y0} }},
		arc(x1-radius, y0+radius, -math.Pi/2, 0),
		{r.H - 2*radius, func(a float32) xy { return xy{x1, y0 + radius + (r.H-2*radius)*a} }},
		arc(x1-radius, y1-radius, 0, math.Pi/2),
		{r.W - 2*radius, func(a float32) xy { return xy{x1 - (r.W-2*radius)*a, y1} }},
		arc(x0+radius, y1-radius, math.Pi/2, math.Pi),
		{r.H - 2*radius, func(a float32) xy { return xy{x0, y1 - (r.H-2*radius)*a} }},
		arc(x0+radius, y0+radius, math.Pi, 3*math.Pi/2),
	}
	total := float32(0)
	for i := range pieces {
		total += pieces[i].length
	}
	// Walk the pieces up to the target, a point about every 1.5 points.
	target := frac * total
	var path ui.Path
	started := false
	cum := float32(0)
	for _, pc := range pieces {
		if target <= cum {
			break
		}
		avail := target - cum
		partial := avail < pc.length
		n := int(min(avail, pc.length)/1.5) + 1
		to := float32(1)
		if partial {
			to = avail / pc.length
		}
		for k := 0; k <= n; k++ {
			q := pc.at(float32(k) / float32(n) * to)
			if !started {
				path.MoveTo(q.X, q.Y)
				started = true
			} else {
				path.LineTo(q.X, q.Y)
			}
		}
		cum += pc.length
	}
	return &path
}

// xy is a point on the ring.
type xy struct{ X, Y float32 }

// Package findbar provides a bar to find within a document, as a
// shadcn/ui component for the FindBar of MyGo: a search field, the
// count and the current match, and buttons to step to the next and the
// previous. The app counts the matches and shows them highlighted.
//
//	findbar.FindBar(c, findbar.Props{
//		Open: &open, Query: &query, Matches: 3, Current: &current,
//	})
package findbar

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the find bar to draw.
type Props struct {
	// Open shows the bar when true; the Escape key and the Done button
	// set it false.
	Open *bool
	// Query is the text being searched for, which the field edits.
	Query *string
	// Matches is the number of times Query occurs, which the app
	// counts; the bar shows "n of m" and steps within it.
	Matches int
	// Current is the index of the match shown, which the bar steps as
	// the user asks.
	Current *int
}

// FindBar draws the search field, the match count, the step buttons and
// the Done button, and returns the bar. Enter and Cmd+G (F3 elsewhere)
// step to the next match, Shift adds the previous, and Escape or Done
// closes. While the bar is closed it draws nothing.
func FindBar(c *ui.Context, p Props) *ui.Element {
	return ui.FindBar(c, p.Open, p.Query, p.Matches, p.Current)
}

// Package form provides a form whose field labels line up, in the way
// macOS draws them: a column of fields, with the label of each to its
// left, right-aligned to the widest. It wraps the Form of MyGo.
//
//	form.Form(c, form.Props{
//		Children: func(c *ui.Context) {
//			ui.Field(c, "Name", func() { input.Input(c, input.Props{Value: &name}) })
//			ui.Field(c, "Email", func() { input.Input(c, input.Props{Value: &email}) })
//		},
//	})
//
// Build each field with the Field of MyGo (or the Fieldset of uix), whose
// labels the form lines up and names for assistive technology; a click on
// a label focuses its control.
package form

import "github.com/egoist/mygo/ui"

// Props describes the form to draw.
type Props struct {
	// Children build the fields of the form, with the Field or the
	// Fieldset of MyGo, whose labels line up at the widest.
	Children func(c *ui.Context)
}

// Form draws a column of the fields that Children builds, with their
// labels to the left, right-aligned to the widest, and returns it.
func Form(c *ui.Context, p Props) *ui.Element {
	if p.Children == nil {
		p.Children = func(c *ui.Context) {}
	}
	return ui.Form(c, func() { p.Children(c) })
}

// Package grid provides a grid layout, as a shadcn/ui component for the
// Grid of MyGo: children placed in cells of columns, which they fill in
// order, or place themselves in with the placement of a cell.
//
//	grid.Grid(c, grid.Props{
//		Columns: 3,
//		Gap:     12,
//		Children: func(c *ui.Context) {
//			for _, p := range photos {
//				ui.Image(c, p).AspectRatio(1).Fit(ui.Cover)
//			}
//		},
//	})
package grid

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the grid to draw.
type Props struct {
	// Columns are the columns of equal width.
	Columns int
	// ColumnTracks set the columns instead, each a width: Fixed, Fr or
	// Auto.
	ColumnTracks []ui.Track
	// Gap spaces the cells.
	Gap float32
	// Children are the cells, which fill the columns in order or place
	// themselves with the placement of their elements, as a header
	// across a grid.
	Children func(c *ui.Context)
}

// Grid draws the grid and returns it. The children fill the columns in
// order; a child places itself with the ColumnStart, RowStart, ColumnSpan
// and RowSpan methods of its element.
func Grid(c *ui.Context, p Props) *ui.Element {
	g := ui.Grid(c)
	if p.Columns > 0 {
		g.Columns(p.Columns)
	}
	if p.ColumnTracks != nil {
		g.ColumnTracks(p.ColumnTracks...)
	}
	if p.Gap > 0 {
		g.Gap(p.Gap)
	}
	if p.Children != nil {
		g.Children(func() { p.Children(c) })
	}
	return g
}

// Package gridview provides a scrolling grid of items, as a shadcn/ui
// component for the GridView of MyGo: as many columns as items of a
// minimum width fit, a click chooses an item, and the arrow keys move
// the choice around.
//
//	gridview.GridView(c, gridview.Props{
//		State:    &state,
//		Count:    len(photos),
//		MinWidth: 140,
//		Height:   120,
//		Item: func(c *ui.Context, i int) {
//			ui.Image(c, photos[i]).Fit(ui.Contain).Grow(1)
//		},
//	})
package gridview

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the grid view to draw.
type Props struct {
	// State keeps the place and the choice of the grid, which the app
	// owns. Set its Selected to let a click choose an item, as the
	// arrow keys do while the grid has the focus.
	State *ui.GridState
	// Count is the number of items.
	Count int
	// MinWidth is the least width of an item; as many columns as fit
	// share the width.
	MinWidth float32
	// Height is the height of every item.
	Height float32
	// Item draws item i, in a cell the grid styles when it is chosen.
	Item func(c *ui.Context, i int)
	// OnChoose runs when a click or the arrow keys choose an item.
	OnChoose func(i int)
}

// GridView draws the items in a scrolling grid, and returns it. A click
// or the arrow keys choose an item when State.Selected is set, and the
// chosen cell shows its choice.
func GridView(c *ui.Context, p Props) *ui.Element {
	g := ui.GridView(c, p.State, p.Count, p.MinWidth, p.Height, func(i int) {
		if p.Item != nil {
			p.Item(c, i)
		}
	})
	if p.OnChoose != nil && g.Changed() && p.State != nil && p.State.Selected != nil {
		p.OnChoose(*p.State.Selected)
	}
	return g
}

// Package icon provides an SVG shown as an icon, in the color of the
// text around it, for the Icon of MyGo.
//
//	icon.Icon(c, icon.Props{
//		SVG:   save,
//		Label: "Save",
//	})
//
// The icon is as high as the font of the text around it, keeping the
// aspect of the SVG, and does not stretch across a column. The color
// follows the text: the theme of the Context, or a TextColor set on the
// row around it. Size fits it into another box, and Grayscale draws it
// without color. Icons are decorations that assistive technology does
// not see, unless Label names them.
package icon

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the icon to draw.
type Props struct {
	// SVG is the shape of the icon, in currentColor so it takes the
	// color of the text.
	SVG *ui.SVG
	// Label names the icon for assistive technology; without it the
	// icon is a decoration it skips.
	Label string
	// Width and Height, when set, fit the icon into a box of that size,
	// instead of the height of the font.
	Width, Height float32
	// Grayscale draws the icon in shades of gray.
	Grayscale bool
}

// Icon draws the SVG as an icon and returns it, so a view can chain more
// calls on it.
func Icon(c *ui.Context, p Props) *ui.Element {
	e := ui.Icon(c, p.SVG)
	if p.Label != "" {
		e.Label(p.Label)
	}
	if p.Width > 0 && p.Height > 0 {
		e.Size(p.Width, p.Height)
	}
	if p.Grayscale {
		e.Grayscale()
	}
	return e
}

// Package image provides a bitmap or an SVG shown as a picture, for the
// Image of MyGo.
//
//	image.Image(c, image.Props{
//		Src:     photo,
//		Width:   120,
//		Height:  90,
//		Fit:     ui.ScaleDown,
//	})
//
// The picture shows at the size of its source, in DIPs, unless Width and
// Height fit it into another box, scaled by Fit: ScaleDown fits it within
// without enlarging it, and the default, Contain, fits it within whatever
// the size needs, keeping the aspect. Width alone fits it into a box of
// its own aspect, and Height alone into one of the aspect of the source.
// Grayscale draws it without color.
package image

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the picture to draw.
type Props struct {
	// Src is the picture: a *ui.Bitmap, or an *ui.SVG in its own colors.
	Src ui.ImageSource
	// Width and Height, when set, fit the picture into a box of that
	// size. One of them alone keeps the aspect of the source; neither
	// shows the picture at its own size.
	Width, Height float32
	// Fit scales the picture to the box: the zero value, Contain, fits
	// it within keeping the aspect, ScaleDown only where that is
	// smaller, Cover crops to cover it, and FillBox stretches it.
	Fit ui.Fit
	// Grayscale draws the picture in shades of gray.
	Grayscale bool
}

// Image draws the picture and returns it, so a view can chain more calls
// on it.
func Image(c *ui.Context, p Props) *ui.Element {
	e := ui.Image(c, p.Src)
	if p.Width > 0 || p.Height > 0 {
		switch {
		case p.Width > 0 && p.Height > 0:
			e.Size(p.Width, p.Height)
		case p.Width > 0:
			e.Width(p.Width)
		case p.Height > 0:
			e.Height(p.Height)
		}
	}
	if p.Fit != 0 {
		e.Fit(p.Fit)
	}
	if p.Grayscale {
		e.Grayscale()
	}
	return e
}

// Package input provides a shadcn/ui-style text field for the MyGo native
