// Package linechart provides the RevenueChartCard of BoardUI for the
// MyGo native toolkit: a card of a year of monthly values drawn against
// the year before. The current year is the filled area and the solid
// line, the year before the dashed line behind it, so the gap between
// them is the story. Resting the pointer on a month swaps the headline
// for that month and shows what it was a year earlier.
//
//	linechart.LineChart(c, linechart.Props{
//		Data:     months,
//		Selected: &active,
//		Title:    "Revenue",
//	})
//
// The card is a rounded panel on the theme's Surface with the headline
// and legend above the plot. The chart needs no legend text of its own
// — the two series read by color — but the legend names them. The card
// fills the height it is given, so a dashboard row can size it with
// Grow.
package linechart

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"github.com/egoist/mygo/ui"
)

// Point is one month of the series.
type Point struct {
	// Label is the short month name, such as "Jan", on the axis.
	Label string
	// Current is the value of the current year.
	Current float64
	// Previous is the value of the year before.
	Previous float64
}

// Props describes the chart to draw.
type Props struct {
	// Data are the months, in order.
	Data []Point
	// Selected is the month under the pointer, by index, -1 for none.
	// The chart keeps it as the pointer moves over the plot and clears
	// it as the pointer leaves; pass nil to draw a chart that does not
	// follow the pointer.
	Selected *int
	// Title is the headline's label when no month is under the pointer.
	Title string
}

// months are the full names of the year, for the headline of the month
// under the pointer.
var months = []string{
	"January", "February", "March", "April", "May", "June",
	"July", "August", "September", "October", "November", "December",
}

// LineChart draws the card and returns it, so a view can chain more
// calls on it.
func LineChart(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	selected := -1
	if p.Selected != nil {
		selected = *p.Selected
	}
	title := p.Title
	if title == "" {
		title = "Revenue"
	}
	label, current, previous, delta, up := headline(t, p.Data, selected, title)
	return ui.Column(c).Fill().Background(t.Surface).Radius(t.Radius * 2).
		Padding(t.Space(4), t.Space(4), t.Space(3), t.Space(4)).
		Gap(t.Space(4)).Children(func() {
		chartHeader(c, t, label, current, previous, delta, up)
		plot(c, t, p)
	})
}

// headline is what the header says: the total, or the month under the
// pointer and its year-earlier figure.
func headline(t *ui.Theme, data []Point, selected int, title string) (label, current, previous, delta string, up bool) {
	if selected >= 0 && selected < len(data) {
		pt := data[selected]
		label = pt.Label
		if len(pt.Label) >= 3 {
			if i := strings.Index("JanFebMarAprMayJunJulAugSepOctNovDec", pt.Label[:3]); i >= 0 {
				label = months[i/3]
			}
		}
		current, previous = formatMoney(pt.Current), formatMoney(pt.Previous)
		delta, up = deltaOf(pt.Current, pt.Previous)
		return
	}
	var sumCur, sumPrev float64
	for _, pt := range data {
		sumCur += pt.Current
		sumPrev += pt.Previous
	}
	label = title
	current, previous = formatMoney(sumCur), formatMoney(sumPrev)
	delta, up = deltaOf(sumCur, sumPrev)
	return
}

// chartHeader is the headline over the plot: the label, the value with
// its delta chip, the comparison under it, and the legend on the right.
func chartHeader(c *ui.Context, t *ui.Theme, label, current, previous, delta string, up bool) {
	ui.Row(c).FillWidth().Justify(ui.SpaceBetween).AlignItems(ui.Start).
		Gap(t.Space(3)).Children(func() {
		ui.Column(c).Gap(3).Children(func() {
			ui.Text(c, label).TextColor(t.TextMuted).SingleLine()
			ui.Row(c).AlignItems(ui.Center).Gap(t.Space(2)).Children(func() {
				ui.Text(c, current).FontSize(t.FontSize * 1.2).FontWeight(600).
					TextColor(t.Text).SingleLine()
				deltaChip(c, t, delta, up)
			})
			ui.Text(c, previous+" last year").FontSize(t.FontSize * 0.8).
				TextColor(t.TextMuted).SingleLine()
		})
		ui.Row(c).Gap(t.Space(4)).Children(func() {
			legend(c, t, t.Success, "This year")
			legend(c, t, t.Text.Alpha(0.3), "Last year")
		})
	})
}

// legend is one named color dot.
func legend(c *ui.Context, t *ui.Theme, color ui.Color, name string) {
	ui.Row(c).Gap(t.Space(1)).AlignItems(ui.Center).Children(func() {
		ui.Box(c).Size(8, 8).Radius(4).Background(color)
		ui.Text(c, name).FontSize(t.FontSize * 0.8).TextColor(t.TextMuted).SingleLine()
	})
}

// plot is the chart itself: the grid, the series, the markers, and the
// invisible columns that feel the pointer.
func plot(c *ui.Context, t *ui.Theme, p Props) {
	plotBox := ui.Box(c).Grow(1).MinHeight(0)
	selected := -1
	if p.Selected != nil {
		hovered := -1
		// The invisible columns, one per month, tile the plot: the
		// pointer over one picks the month, over the margins clears it.
		plotBox.Children(func() {
			ui.Row(c).Fill().Padding(8, 8, 22, 40).Children(func() {
				for i := range p.Data {
					col := ui.Box(c).Grow(1).FillHeight()
					col.Label(p.Data[i].Label)
					if col.Hovered() {
						hovered = i
					}
				}
			})
		})
		if plotBox.Hovered() {
			*p.Selected = hovered
		} else {
			*p.Selected = -1
		}
		selected = *p.Selected
	}
	plotBox.Draw(func(pt *ui.Painter, r ui.Rect) {
		drawPlot(pt, t, p.Data, selected, r)
	})
}

// drawPlot paints the grid, the year before as a dashed line, the
// current year as the filled area and the solid line, and the marker of
// the month under the pointer.
func drawPlot(pt *ui.Painter, t *ui.Theme, data []Point, selected int, r ui.Rect) {
	n := len(data)
	if n == 0 {
		return
	}
	plot := ui.Rect{X: r.X + 40, Y: r.Y + 8, W: r.W - 48, H: r.H - 30}
	var scale float64
	for _, p := range data {
		if m := math.Max(p.Current, p.Previous); m > scale {
			scale = m
		}
	}
	scale *= 1.1
	if scale == 0 {
		scale = 1
	}
	y := func(v float64) float32 {
		return plot.Y + plot.H*float32(1-v/scale)
	}
	// The grid, four lines with their labels right-aligned on the left.
	for i := 0; i < 4; i++ {
		gy := plot.Y + plot.H*float32(i)/3
		pt.Line(plot.X, gy, plot.X+plot.W, gy, 1, t.Border)
		label := formatK(scale * float64(3-i) / 3)
		size := t.FontSize * 0.75
		w := float32(len(label)) * size * 0.55
		pt.Text(plot.X-8-w, gy+size*0.35, label, size, t.TextMuted)
	}
	// The band the plot has, so every column reads its center.
	band := plot.W / float32(n)
	prev := make([]xy, n)
	cur := make([]xy, n)
	for i, p := range data {
		x := plot.X + band*(float32(i)+0.5)
		prev[i] = xy{x, y(p.Previous)}
		cur[i] = xy{x, y(p.Current)}
	}
	// The year before, dashed, as the story behind the area.
	dashLine(pt, prev, 5, 5, 2, t.Text.Alpha(0.3))
	// The current year's area, fading down from the line.
	area(pt, t, cur, plot)
	// The current year's line.
	stroke(pt, cur, 2.5, t.Success)
	// The month under the pointer, marked with a bright dot and a halo.
	if selected >= 0 && selected < n {
		p := cur[selected]
		var halo ui.Path
		halo.Circle(p.X, p.Y, 7)
		pt.FillPath(&halo, t.Success.Alpha(0.25))
		var dot ui.Path
		dot.Circle(p.X, p.Y, 4)
		pt.FillPath(&dot, t.Success)
	}
	// The month names under the axis.
	size := t.FontSize * 0.75
	for i, p := range data {
		w := float32(len(p.Label)) * size * 0.55
		pt.Text(cur[i].X-w/2, plot.Y+plot.H+18, p.Label, size, t.TextMuted)
	}
}

// area fills the space under the current line, fading down: thin bands
// at every step of x, each a little fainter, so the fill reads as a
// vertical gradient.
func area(pt *ui.Painter, t *ui.Theme, pts []xy, plot ui.Rect) {
	const bands = 4
	bottom := plot.Y + plot.H
	for x := plot.X; x <= plot.X+plot.W; x += 2 {
		top := lineY(pts, x)
		for b := 0; b < bands; b++ {
			bTop := top + float32(b)*(plot.H/bands)
			if bTop >= bottom {
				break
			}
			bBottom := min(bTop+plot.H/bands, bottom)
			a := float32(0.3) * (1 - float32(b)/bands)
			pt.Fill(ui.Rect{X: x, Y: bTop, W: 2, H: bBottom - bTop}, t.Success.Alpha(a), 0)
		}
	}
}

// lineY is the height of the line at x, between its points.
func lineY(pts []xy, x float32) float32 {
	if x <= pts[0].X {
		return pts[0].Y
	}
	for i := 1; i < len(pts); i++ {
		if x <= pts[i].X {
			t := (x - pts[i-1].X) / (pts[i].X - pts[i-1].X)
			return pts[i-1].Y + (pts[i].Y-pts[i-1].Y)*t
		}
	}
	return pts[len(pts)-1].Y
}

// stroke joins the points with a line.
func stroke(pt *ui.Painter, pts []xy, width float32, c ui.Color) {
	var p ui.Path
	p.MoveTo(pts[0].X, pts[0].Y)
	for i := 1; i < len(pts); i++ {
		p.LineTo(pts[i].X, pts[i].Y)
	}
	pt.StrokePath(&p, width, c)
}

// dashLine draws the points as a dashed line, the dashes running
// continuously across the points rather than restarting at each one.
func dashLine(pt *ui.Painter, pts []xy, dash, gap, width float32, c ui.Color) {
	var carry float32
	on := true
	for i := 1; i < len(pts); i++ {
		ax, ay := pts[i-1].X, pts[i-1].Y
		bx, by := pts[i].X, pts[i].Y
		seg := float32(math.Hypot(float64(bx-ax), float64(by-ay)))
		if seg == 0 {
			continue
		}
		for t := float32(0); t < seg; {
			step := dash
			if !on {
				step = gap
			}
			run := min(step-carry, seg-t)
			if on {
				x0 := ax + (bx-ax)*(t/seg)
				y0 := ay + (by-ay)*(t/seg)
				x1 := ax + (bx-ax)*((t+run)/seg)
				y1 := ay + (by-ay)*((t+run)/seg)
				pt.Line(x0, y0, x1, y1, width, c)
			}
			t += run
			carry += run
			if carry >= step {
				carry = 0
				on = !on
			}
		}
	}
}

// deltaChip is the pill of the change, green for a gain, red for a
// loss, plain for a tie.
func deltaChip(c *ui.Context, t *ui.Theme, delta string, up bool) {
	flat := delta == "0%" || delta == "New"
	bg, fg := t.SurfaceHover, t.TextMuted
	if up {
		bg, fg = t.Success.Alpha(0.15), t.Success
	} else if !flat {
		bg, fg = t.Danger.Alpha(0.15), t.Danger
	}
	ui.Row(c).Shrink(0).Gap(3).Radius(9).Padding(2, 4).
		AlignItems(ui.Center).Background(bg).Children(func() {
		ui.Box(c).Size(12, 12).Draw(func(pt *ui.Painter, r ui.Rect) {
			cx, cy := r.X+r.W/2, r.Y+r.H/2
			if up {
				pt.Line(cx, cy+2.5, cx, cy-2.5, 1.6, fg)
				var p ui.Path
				p.MoveTo(cx-1.8, cy-0.5).LineTo(cx, cy-2.5).LineTo(cx+1.8, cy-0.5)
				pt.StrokePath(&p, 1.6, fg)
			} else if flat {
				pt.Line(cx-2.5, cy, cx+2.5, cy, 1.6, fg)
			} else {
				pt.Line(cx, cy-2.5, cx, cy+2.5, 1.6, fg)
				var p ui.Path
				p.MoveTo(cx-1.8, cy+0.5).LineTo(cx, cy+2.5).LineTo(cx+1.8, cy+0.5)
				pt.StrokePath(&p, 1.6, fg)
			}
		})
		ui.Text(c, delta).FontSize(t.FontSize * 0.8).TextColor(fg).SingleLine()
	})
}

// deltaOf is the change of current against previous: the label of the
// chip and whether it reads as a gain.
func deltaOf(current, previous float64) (label string, up bool) {
	if previous == 0 {
		return "New", false
	}
	change := (current - previous) / previous * 100
	rounded := math.Round(change*10) / 10
	if rounded == 0 {
		return "0%", false
	}
	if rounded > 0 {
		return fmt.Sprintf("+%s%%", strconv.FormatFloat(rounded, 'f', -1, 64)), true
	}
	return fmt.Sprintf("%s%%", strconv.FormatFloat(rounded, 'f', -1, 64)), false
}

// formatK is the axis label: "$14k" for the thousands, "$0" below.
func formatK(v float64) string {
	if v >= 1000 {
		return fmt.Sprintf("$%dk", int(math.Round(v/1000)))
	}
	return fmt.Sprintf("$%d", int(v))
}

// formatMoney is the headline figure as currency, rounded to the dollar
// with thousands separators: "$14,392".
func formatMoney(v float64) string {
	return "$" + grouped(int64(math.Round(v)))
}

// grouped writes n with a comma before every third digit.
func grouped(n int64) string {
	s := strconv.FormatInt(n, 10)
	start := len(s) % 3
	if start == 0 && len(s) > 3 {
		start = 3
	}
	var b strings.Builder
	for i, r := range s {
		if i > 0 && i == start {
			b.WriteByte(',')
		} else if i > start && (i-start)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}

// xy is a point of the plot.
type xy struct{ X, Y float32 }

// Package link provides a text that opens a URL in the browser when it
// is clicked, as a shadcn/ui component for the Link of MyGo.
//
//	link.Link(c, link.Props{
//		Label: "Read the guide",
//		URL:   "https://example.com/guide",
//	})
//
// The label shows in the accent color, and gains an underline when the
// pointer rests on it. In a page of a Router, a URL without a scheme, as
// "/notes/42", goes there in the router instead of the browser.
package link

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the link to draw.
type Props struct {
	// Label is the text of the link.
	Label string
	// URL is what the link opens: an address for the browser, or a path
	// for the Router the page lives in.
	URL string
}

// Link draws the label as a link that opens URL when clicked or Entered,
// and returns it.
func Link(c *ui.Context, p Props) *ui.Element {
	return ui.Link(c, p.Label, p.URL)
}

// Package list provides a scrolling list of rows, from the mygo List
// widget. The list builds only the rows in view and keeps its place
// among them; choosing a row highlights it in the accent color.
package list

import (
	"github.com/egoist/mygo/ui"
)

// Props configure the list.
type Props struct {
	// State is the place and the choice of the list, kept from frame
	// to frame. Give each list a state of its own, and set its fields
	// before building: to let the user choose a row, set
	// State.Selected = &app.Chosen, where app.Chosen is the row
	// chosen, -1 for none.
	State *ui.ListState
	// Items are the rows, each shown as its text, unless Row draws it.
	// Items also count the rows, so a Row builder changes only the
	// look, not the number.
	Items []string
	// Row draws row i in place of its text; nil shows Items[i] in a
	// line of the theme's height.
	Row func(c *ui.Context, i int)
	// OnChoose runs when the user chooses a row: i is the row chosen.
	// It needs State.Selected, which names the choice.
	OnChoose func(i int)
	// Disabled keeps the list from choosing rows.
	Disabled bool
}

// List draws the items as a scrolling list. A click chooses a row, as
// the arrow keys and Home and End do while the list has the keyboard
// focus; a double click or Enter submits it.
func List(c *ui.Context, p Props) *ui.Element {
	e := ui.List(c, p.State, len(p.Items), func(i int) {
		if p.Row != nil {
			p.Row(c, i)
			return
		}
		// The row shows its text across the list, as a row of the
		// gallery's lists does, so the chosen row highlights along the
		// whole list.
		ui.Row(c).Height(32).PaddingX(12).Children(func() {
			ui.Text(c, p.Items[i]).Grow(1)
		})
	})
	if p.OnChoose != nil && e.Changed() && p.State != nil && p.State.Selected != nil {
		p.OnChoose(*p.State.Selected)
	}
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package log provides the AgentLog of BoardUI for the MyGo native
// toolkit: a transcript of an agent's work, each line joined to the next
// by a curved tree guide, with a working row of stars while the agent is
// still going. It is the machinery of a streaming transcript; what a row
// says is the app's own business.
//
//	log.Log(c, log.Props{
//		Items:    steps,
//		Revealed: revealed,
//		Running:  working,
//		Working:  "Searching the docs",
//	})
//
// The reveal is the app's own pacing, not the component's: pass how many
// items are shown, and the app advances it with a timer or with the real
// events of the work, so the log never pretends steps take equal time.
package log

import (
	"github.com/egoist/mygo/ui"

	"github.com/smallnest/uix/components/thinking"
)

// Props describes the log to draw.
type Props struct {
	// Items are the lines of the work, in order.
	Items []string
	// Revealed is how many items are shown, as the app has paced them;
	// it is clamped to the length of Items. 0 shows none.
	Revealed int
	// Running shows the working row below the revealed items, with the
	// stars indicator, while the log is still going.
	Running bool
	// Working is the label of the working row, such as "Searching the
	// docs".
	Working string
}

// Log draws the transcript and returns it, so a view can chain more
// calls on it.
func Log(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	n := min(p.Revealed, len(p.Items))
	return ui.Column(c).FillWidth().Gap(t.Space(1)).Children(func() {
		for i := 0; i < n; i++ {
			row(c, t, p.Items[i], i == n-1)
		}
		if p.Running {
			workingRow(c, t, p.Working)
		}
	})
}

// row is one completed line of work, with the stretch of guide that
// belongs to it: a branch at the top and a trunk running to the next
// row, which the last row omits so the guide finishes on the corner.
func row(c *ui.Context, t *ui.Theme, label string, last bool) {
	guide := t.TextMuted.Alpha(0.45)
	ui.Row(c).FillWidth().AlignItems(ui.Stretch).Children(func() {
		// The branch geometry, as the docs sidebar draws it: down the
		// trunk, round a corner at 14px, out to the label.
		ui.Box(c).Width(12).Shrink(0).Draw(func(pt *ui.Painter, r ui.Rect) {
			var branch ui.Path
			branch.MoveTo(r.X+0.5, r.Y)
			branch.LineTo(r.X+0.5, r.Y+8)
			branch.QuadTo(r.X+0.5, r.Y+14, r.X+6.5, r.Y+14)
			branch.LineTo(r.X+11.5, r.Y+14)
			pt.StrokePath(&branch, 1, guide)
			if !last {
				pt.Line(r.X+0.5, r.Y+14, r.X+0.5, r.Y+r.H, 1, guide)
			}
		})
		ui.Text(c, label).TextColor(t.Text).Padding(0, t.Space(1))
	})
}

// workingRow is the line the agent is on now, with the stars indicator.
// It deliberately sits off the guide: the tree records what the agent
// did, and this line has not happened yet, so hanging it on the tree
// would file it alongside the findings.
func workingRow(c *ui.Context, t *ui.Theme, label string) {
	ui.Row(c).Padding(0, t.Space(1)).Children(func() {
		thinking.Thinking(c, thinking.Props{
			Variant: thinking.Stars,
			Label:   label,
			Tone:    thinking.Subtle,
		})
	})
}

// Package menu provides a shadcn/ui-style Menu: a button showing a label
// and an arrow, which opens a menu below it, as the pointer goes down on
// it, or for Enter, Space or Down while it has the focus. The menu holds
// the items of the Props, one above the other; choosing one runs its
// Action and closes the menu. An item may show a check and be disabled;
// a Separator item draws a line between the items.
//
//	menu.Menu(c, menu.Props{
//		Label: "File",
//		Items: []menu.Item{
//			{Label: "New", Action: func() { app.new() }},
//			{Separator: true},
//			{Label: "Save", Checked: app.dirty, Action: func() { app.save() }},
//		},
//	})
package menu

import "github.com/egoist/mygo/ui"

// Item is one entry of a Menu.
type Item struct {
	// Label is the text of the item.
	Label string
	// Checked shows a check beside the label, as for a setting that is
	// on.
	Checked bool
	// Disabled keeps the item from being chosen.
	Disabled bool
	// Separator draws a line instead of an item, as between groups of
	// items; the other fields are ignored.
	Separator bool
	// Action runs when the item is chosen; nil for none.
	Action func()
}

// Props describes the menu to draw.
type Props struct {
	// Label is the text of the button, such as "File".
	Label string
	// Items are the entries of the menu, in order.
	Items []Item
	// Disabled keeps the menu from opening.
	Disabled bool
}

// Menu draws the button, and the menu it opens, and returns the button,
// so a view can chain more calls on it.
func Menu(c *ui.Context, p Props) *ui.Element {
	e := ui.MenuButton(c, p.Label, func(m *ui.Menu) {
		for _, it := range p.Items {
			if it.Separator {
				m.Separator()
				continue
			}
			item := m.Item(it.Label)
			item.Checked(it.Checked).Disabled(it.Disabled)
			if item.Chosen() && it.Action != nil {
				it.Action()
			}
		}
	})
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package meter provides a shadcn/ui-style meter: a bar that shows a
// measure against its range, colored by how near the top it is, with a
// label and a live readout, from the Meter of MyGo.
//
//	meter.Meter(c, meter.Props{
//		Value:  0.78,
//		Max:    1,
//		Label:  "Disk usage",
//		Levels: &ui.MeterLevels{Warning: 0.7, Critical: 0.9},
//	})
package meter

import (
	"fmt"

	"github.com/egoist/mygo/ui"
)

// Props describes the meter to draw.
type Props struct {
	// Value is the measure, between Min and Max.
	Value float64
	// Min and Max bound the measure. A Max at or below Min is taken as 1
	// above Min, so a bare fraction fills the bar.
	Min, Max float64
	// Levels turn the bar the Warning color from its Warning share of the
	// range, and the Danger color from Critical. The zero value keeps the
	// Success color throughout. A Critical below Warning makes low values
	// the bad ones, as a battery's.
	Levels *ui.MeterLevels
	// Label is the text above the bar, next to the readout.
	Label string
	// Format renders the readout; the default prints the rounded value.
	Format func(v float64) string
}

// Meter draws the label, the readout and the bar, and returns the
// column. The readout follows the value as the app changes it, because
// the view builds every frame.
func Meter(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	format := p.Format
	if format == nil {
		format = func(v float64) string { return fmt.Sprintf("%.0f", v) }
	}
	hi := p.Max
	if hi <= p.Min {
		hi = p.Min + 1
	}
	return ui.Column(c).Gap(t.Space(0.5)).Children(func() {
		if p.Label != "" {
			ui.Row(c).Gap(t.Space(2)).Children(func() {
				ui.Text(c, p.Label).FontSize(t.FontSize * 0.875).Bold().TextColor(t.TextMuted)
				ui.Text(c, format(p.Value)).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
			})
		}
		ui.Meter(c, p.Value, p.Min, hi, p.Levels).FillWidth()
	})
}

// Package notificationcenter provides the NotificationCenter of BoardUI
// for the MyGo native toolkit: a panel of notifications with a title, an
// unread count, a mark-all-read control, and tabs that filter the list.
//
//	notificationcenter.NotificationCenter(c, notificationcenter.Props{
//		Items: items,
//		Tab:   &tab,
//	})
//
// The panel is a rounded card on the theme's Background. The list sits
// on a recessed band; each notification is a card with a status icon,
// the title and timestamp, the description, and its actions. The app
// owns the list: it sets the unread flags, and Mark all read asks it to
// clear them.
package notificationcenter

import (
	"fmt"

	"github.com/egoist/mygo/ui"

	"github.com/smallnest/uix/components/segmented"
)

// Status is the tone of a notification's icon.
type Status int

const (
	// Neutral is a general notice, the bell.
	Neutral Status = iota
	// Info is an informational notice, the i.
	Info
	// Success is a notice of something that went well, the check.
	Success
	// Error is a notice of something that went wrong, the bang.
	Error
)

// Action is a button a notification carries, such as "View".
type Action struct {
	// ID names the action for OnAction.
	ID string
	// Label is the text of the button.
	Label string
	// OnClick runs when the button is clicked.
	OnClick func()
}

// Item is one notification.
type Item struct {
	// ID names the notification for OnAction.
	ID string
	// Category is "mentions" or "system"; anything else is general
	// activity, shown on the All tab.
	Category string
	// Title is the headline of the notification.
	Title string
	// Description is the detail under it.
	Description string
	// Timestamp is the time, as the app formats it, such as "2m".
	Timestamp string
	// Unread draws the accent dot and counts toward the unread total.
	Unread bool
	// Status tones the icon; the zero value is Neutral.
	Status Status
	// Actions are the buttons of the notification, in order.
	Actions []Action
}

// Props describes the panel to draw.
type Props struct {
	// Items are the notifications, in order.
	Items []Item
	// Tab is the chosen tab: 0 All, 1 Mentions, 2 System.
	Tab *int
	// OnTabChange runs when a tab is chosen.
	OnTabChange func(i int)
	// OnMarkAllRead runs when Mark all read is clicked; the app clears
	// the unread flags of its items.
	OnMarkAllRead func()
	// OnAction runs when a notification's action is clicked, with the
	// notification and the action, and then the action's own OnClick.
	OnAction func(itemID, actionID string)
	// Title is the heading of the panel; "Notifications" when empty.
	Title string
	// EmptyMessage is shown for an empty tab; "You're all caught up."
	// when empty.
	EmptyMessage string
	// Height, when set, caps the list and scrolls it; 0 grows the panel
	// to its items.
	Height float32
}

// NotificationCenter draws the panel and returns it, so a view can chain
// more calls on it.
func NotificationCenter(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	title := p.Title
	if title == "" {
		title = "Notifications"
	}
	empty := p.EmptyMessage
	if empty == "" {
		empty = "You're all caught up."
	}
	unread := 0
	for _, it := range p.Items {
		if it.Unread {
			unread++
		}
	}
	return ui.Column(c).FillWidth().Background(t.Background).Radius(t.Radius * 3).
		Border(1, t.Border).Children(func() {
		ui.Column(c).Padding(t.Space(4), t.Space(4), t.Space(1.5), t.Space(4)).
			Gap(t.Space(3)).Children(func() {
			header(c, t, p, title, unread)
			tabs(c, t, p)
		})
		list(c, t, p, empty)
	})
}

// header is the title, the unread count and the mark-all-read control.
func header(c *ui.Context, t *ui.Theme, p Props, title string, unread int) {
	ui.Row(c).FillWidth().Justify(ui.SpaceBetween).AlignItems(ui.Start).
		Gap(t.Space(4)).Children(func() {
		ui.Column(c).Gap(2).Children(func() {
			ui.Text(c, title).FontSize(t.FontSize * 1.1).FontWeight(600).TextColor(t.Text)
			sub := "No unread notifications"
			if unread > 0 {
				sub = fmt.Sprintf("%d unread", unread)
			}
			ui.Text(c, sub).TextColor(t.TextMuted)
		})
		markAll(c, t, p, unread)
	})
}

// markAll is the ghost control that clears the unread flags, disabled
// when there is nothing unread.
func markAll(c *ui.Context, t *ui.Theme, p Props, unread int) {
	b := ui.ButtonBase(c).Radius(t.Radius).Padding(t.Space(1.5), t.Space(2.5))
	b.Disabled(unread == 0)
	b.Label("Mark all read")
	if b.Clicked() && p.OnMarkAllRead != nil {
		p.OnMarkAllRead()
	}
	b.Children(func() {
		ui.Text(c, "Mark all read").FontSize(t.FontSize * 0.85).TextColor(t.TextMuted).SingleLine()
	})
}

// tabs is the segmented control with the per-tab counts.
func tabs(c *ui.Context, t *ui.Theme, p Props) {
	var all, mentions, system int
	for _, it := range p.Items {
		all++
		switch it.Category {
		case "mentions":
			mentions++
		case "system":
			system++
		}
	}
	segmented.Segmented(c, segmented.Props{
		Selected: p.Tab,
		Labels: []string{
			fmt.Sprintf("All %d", all),
			fmt.Sprintf("Mentions %d", mentions),
			fmt.Sprintf("System %d", system),
		},
		OnChange: p.OnTabChange,
		Label:    "Notification category",
	})
}

// list is the recessed band of notifications, or the empty message.
func list(c *ui.Context, t *ui.Theme, p Props, empty string) {
	visible := p.Items
	tab := 0
	if p.Tab != nil {
		tab = *p.Tab
	}
	switch tab {
	case 1:
		visible = filterCategory(p.Items, "mentions")
	case 2:
		visible = filterCategory(p.Items, "system")
	}
	band := func() {
		ui.Column(c).Gap(t.Space(2)).Children(func() {
			if len(visible) == 0 {
				emptyState(c, t, empty)
				return
			}
			for _, it := range visible {
				itemRow(c, t, p, it)
			}
		})
	}
	if p.Height > 0 {
		ui.Scroll(c).Height(p.Height).Children(band).Padding(t.Space(1.5)).
			Background(t.SurfaceHover).Radius(t.Radius * 2)
	} else {
		ui.Column(c).Padding(t.Space(1.5)).Background(t.SurfaceHover).
			Radius(t.Radius * 2).Children(band)
	}
}

// filterCategory keeps the notifications of one category.
func filterCategory(items []Item, category string) []Item {
	out := make([]Item, 0, len(items))
	for _, it := range items {
		if it.Category == category {
			out = append(out, it)
		}
	}
	return out
}

// itemRow is one notification card.
func itemRow(c *ui.Context, t *ui.Theme, p Props, it Item) {
	ui.Row(c).FillWidth().Gap(t.Space(3)).Padding(t.Space(3)).
		Background(t.Background).Radius(t.Radius * 2).Children(func() {
		statusCircle(c, t, it.Status)
		ui.Column(c).Grow(1).Gap(2).Children(func() {
			ui.Row(c).FillWidth().Gap(t.Space(2)).Children(func() {
				ui.Text(c, it.Title).Grow(1).TextColor(t.Text).SingleLine()
				ui.Text(c, it.Timestamp).FontSize(t.FontSize * 0.8).
					TextColor(t.TextMuted).SingleLine()
				if it.Unread {
					ui.Box(c).Size(8, 8).Radius(4).Background(t.Accent).
						Label("Unread")
				}
			})
			ui.Text(c, it.Description).TextColor(t.TextMuted)
			if len(it.Actions) > 0 {
				ui.Row(c).Gap(t.Space(2)).Children(func() {
					for _, a := range it.Actions {
						actionButton(c, t, p, it, a)
					}
				})
			}
		})
	})
}

// actionButton is one action of a notification.
func actionButton(c *ui.Context, t *ui.Theme, p Props, it Item, a Action) {
	b := ui.ButtonBase(c).Radius(t.Radius).Background(t.Surface).
		Padding(t.Space(1.5), t.Space(2.5))
	if b.Clicked() {
		if p.OnAction != nil {
			p.OnAction(it.ID, a.ID)
		}
		if a.OnClick != nil {
			a.OnClick()
		}
	}
	b.Children(func() {
		ui.Text(c, a.Label).FontSize(t.FontSize * 0.85).TextColor(t.Text).SingleLine()
	})
}

// statusCircle is the round tile with the status icon.
func statusCircle(c *ui.Context, t *ui.Theme, status Status) {
	bg, fg := t.SurfaceHover, t.TextMuted
	switch status {
	case Info:
		bg, fg = t.Accent.Alpha(0.12), t.Accent
	case Success:
		bg, fg = t.Success.Alpha(0.15), t.Success
	case Error:
		bg, fg = t.Danger.Alpha(0.12), t.Danger
	}
	ui.Box(c).Size(40, 40).Radius(20).Background(bg).Shrink(0).Center().
		Children(func() {
			switch status {
			case Info:
				info(c, fg)
			case Success:
				check(c, fg)
			case Error:
				bang(c, fg)
			default:
				bell(c, fg)
			}
		})
}

// emptyState is the message of an empty tab.
func emptyState(c *ui.Context, t *ui.Theme, message string) {
	ui.Column(c).FillWidth().Center().Gap(t.Space(2)).
		Padding(0, t.Space(6)).Children(func() {
		ui.Box(c).Size(44, 44).Radius(22).Background(t.Surface).Center().
			Children(func() { bellOff(c, t.TextMuted) })
		ui.Text(c, message).TextColor(t.Text)
		ui.Text(c, "New activity will appear here when it arrives.").
			TextColor(t.TextMuted).TextAlign(ui.Center)
	})
}

// bell draws the neutral bell: a dome, a base, a clapper.
func bell(c *ui.Context, color ui.Color) {
	icon(c, func(pt *ui.Painter, cx, cy float32) {
		var dome ui.Path
		dome.MoveTo(cx-6, cy+2.5)
		dome.QuadTo(cx-6.5, cy-2.5, cx-3, cy-5.5)
		dome.QuadTo(cx-1, cy-6.5, cx, cy-6.5)
		dome.QuadTo(cx+1, cy-6.5, cx+3, cy-5.5)
		dome.QuadTo(cx+6.5, cy-2.5, cx+6, cy+2.5)
		pt.StrokePath(&dome, 1.6, color)
		var base ui.Path
		base.MoveTo(cx-5.5, cy+2.5).LineTo(cx+5.5, cy+2.5)
		pt.StrokePath(&base, 1.6, color)
		var clapper ui.Path
		clapper.Circle(cx, cy+4.5, 1.3)
		pt.FillPath(&clapper, color)
	})
}

// bellOff draws the bell with a slash over it, for an empty tab.
func bellOff(c *ui.Context, color ui.Color) {
	icon(c, func(pt *ui.Painter, cx, cy float32) {
		var dome ui.Path
		dome.MoveTo(cx-6, cy+2.5)
		dome.QuadTo(cx-6.5, cy-2.5, cx-3, cy-5.5)
		dome.QuadTo(cx-1, cy-6.5, cx, cy-6.5)
		dome.QuadTo(cx+1, cy-6.5, cx+3, cy-5.5)
		dome.QuadTo(cx+6.5, cy-2.5, cx+6, cy+2.5)
		pt.StrokePath(&dome, 1.6, color)
		var slash ui.Path
		slash.MoveTo(cx-7, cy-7).LineTo(cx+7, cy+7)
		pt.StrokePath(&slash, 1.6, color)
	})
}

// info draws the i of an informational notice.
func info(c *ui.Context, color ui.Color) {
	icon(c, func(pt *ui.Painter, cx, cy float32) {
		var ring ui.Path
		ring.Circle(cx, cy, 8)
		pt.StrokePath(&ring, 1.6, color)
		var dot ui.Path
		dot.Circle(cx, cy-3.5, 1.2)
		pt.FillPath(&dot, color)
		pt.Line(cx, cy-1, cx, cy+4.5, 1.6, color)
	})
}

// check draws the check of a success notice.
func check(c *ui.Context, color ui.Color) {
	icon(c, func(pt *ui.Painter, cx, cy float32) {
		var p ui.Path
		p.MoveTo(cx-5, cy).LineTo(cx-1.5, cy+3.5).LineTo(cx+5.5, cy-3.5)
		pt.StrokePath(&p, 2, color)
	})
}

// bang draws the bang of an error notice.
func bang(c *ui.Context, color ui.Color) {
	icon(c, func(pt *ui.Painter, cx, cy float32) {
		var ring ui.Path
		ring.Circle(cx, cy, 8)
		pt.StrokePath(&ring, 1.6, color)
		pt.Line(cx, cy-4.5, cx, cy+0.5, 1.8, color)
		var dot ui.Path
		dot.Circle(cx, cy+3.8, 1.2)
		pt.FillPath(&dot, color)
	})
}

// icon runs fn over a 20-point icon centered in the box.
func icon(c *ui.Context, fn func(pt *ui.Painter, cx, cy float32)) {
	ui.Box(c).Size(20, 20).Shrink(0).Draw(func(pt *ui.Painter, r ui.Rect) {
		fn(pt, r.X+r.W/2, r.Y+r.H/2)
	})
}

// Package numberinput provides a shadcn/ui-style NumberInput: a field
// for a number between bounds, which the arrows and the buttons beside
// it step by step.
//
//	numberinput.NumberInput(c, numberinput.Props{
//		Value: &copies,
//		Lo:    1, Hi: 99, Step: 1,
//	})
package numberinput

import "github.com/egoist/mygo/ui"

// Props describes the number input to draw.
type Props struct {
	// Value is the number being edited.
	Value *float64
	// Lo is the smallest value allowed.
	Lo float64
	// Hi is the largest value allowed.
	Hi float64
	// Step is how much the arrows and the buttons change the value.
	Step float64
	// Disabled keeps the field from being edited.
	Disabled bool
}

// NumberInput draws a field editing *Value as a number between Lo and
// Hi, stepped by Step, and returns it, so a view can chain more calls on
// it. What is typed applies as soon as it is a number in range, and
// shows rounded to the decimals of Step once the field loses the focus.
func NumberInput(c *ui.Context, p Props) *ui.Element {
	e := ui.NumberInput(c, p.Value, p.Lo, p.Hi, p.Step)
	if p.Disabled {
		e.Disabled(true)
	}
