// Package pagination provides the pagination of BoardUI for the MyGo
// native toolkit: previous and next buttons and the page numbers, with
// the overflow of a long list of pages collapsing into dots around the
// current page.
//
//	pagination.Pagination(c, pagination.Props{
//		Page:       state.Page,
//		TotalPages: state.Pages,
//		OnChange:   func(p int) { state.Page = p },
//	})
//
// The previous and next buttons sit at the ends, disable at the first
// and last page, and read "Previous" and "Next" unless the app says
// otherwise. The page cells are 32 by 32; the current page is a cell
// with a face, the others fill on hover, and the dots are not buttons.
// The component is controlled: it shows what the app passes and reports
// a click through OnChange, so the app owns the page.
package pagination

import (
	"fmt"

	"github.com/egoist/mygo/ui"
)

// DOTS marks a gap in the page numbers, drawn as an ellipsis.
const DOTS = -1

// Props describes the pagination to draw.
type Props struct {
	// Page is the page shown, from 1.
	Page int
	// TotalPages is how many pages there are.
	TotalPages int
	// OnChange reports the page a button or cell chose.
	OnChange func(page int)
	// SiblingCount is how many pages show on each side of the current
	// page; 1 when zero.
	SiblingCount int
	// PreviousLabel and NextLabel name the end buttons; "Previous" and
	// "Next" when empty.
	PreviousLabel, NextLabel string
}

// Pagination draws the pagination and returns it, so a view can chain
// more calls on it. Nothing is drawn for one page, as BoardUI hides it.
func Pagination(c *ui.Context, p Props) *ui.Element {
	if p.TotalPages <= 1 {
		return ui.Box(c)
	}
	t := c.Theme()
	sibling := p.SiblingCount
	if sibling == 0 {
		sibling = 1
	}
	prev, next := p.PreviousLabel, p.NextLabel
	if prev == "" {
		prev = "Previous"
	}
	if next == "" {
		next = "Next"
	}
	return ui.Row(c).FillWidth().Justify(ui.SpaceBetween).AlignItems(ui.Center).
		Gap(t.Space(2)).Children(func() {
		pagerButton(c, t, prev, false, p.Page <= 1, func() { p.OnChange(p.Page - 1) })
		ui.Row(c).Gap(2).Children(func() {
			for _, item := range pageRange(p.Page, p.TotalPages, sibling) {
				if item == DOTS {
					ui.Box(c).Size(32, 32).Center().Children(func() {
						ui.Text(c, "…").TextColor(t.TextMuted).SingleLine()
					})
					continue
				}
				cell(c, t, item, item == p.Page, func() { p.OnChange(item) })
			}
		})
		pagerButton(c, t, next, true, p.Page >= p.TotalPages, func() { p.OnChange(p.Page + 1) })
	})
}

// cell is one page number: 32 by 32 with rounded corners, the current
// page a raised cell and the others a ghost that fills on hover.
func cell(c *ui.Context, t *ui.Theme, page int, active bool, on func()) {
	b := ui.ButtonBase(c).Size(32, 32).Radius(t.Radius).Center()
	b.Label(fmt.Sprintf("Go to page %d", page))
	fg := t.Text
	if active {
		b.Background(t.Surface).Border(1, t.Border)
	} else {
		// The ghost fills as the pointer rests on it, read each frame so
		// the hover works without a rebuild.
		b.Draw(func(pp *ui.Painter, r ui.Rect) {
			if b.Hovered() {
				pp.Fill(r, t.SurfaceHover, t.Radius)
			}
		})
	}
	b.Children(func() {
		ui.Text(c, fmt.Sprintf("%d", page)).TextColor(fg).SingleLine()
	})
	if b.Clicked() {
		on()
	}
}

// pagerButton is the previous or next button: a chevron with the label,
// a face that follows the pointer, disabled at its end of the pages.
func pagerButton(c *ui.Context, t *ui.Theme, label string, next bool, disabled bool, on func()) {
	b := ui.ButtonBase(c)
	b.Label(label)
	fg := t.Text
	if disabled {
		fg = t.TextMuted
	}
	b.TextColor(fg).Padding(t.Space(1), t.Space(2.5)).Gap(t.Space(1.5)).
		Radius(t.Radius).Border(1, t.Border)
	b.Draw(func(pp *ui.Painter, r ui.Rect) {
		if b.IsDisabled() {
			return
		}
		bg := t.Surface
		switch {
		case b.Pressed():
			bg = t.SurfacePressed
		case b.Hovered():
			bg = t.SurfaceHover
		}
		pp.Fill(r, bg, t.Radius)
	})
	b.Children(func() {
		ui.Row(c).AlignItems(ui.Center).Gap(t.Space(1)).Children(func() {
			if next {
				ui.Text(c, label).SingleLine()
				chevron(c, t, fg, true)
			} else {
				chevron(c, t, fg, false)
				ui.Text(c, label).SingleLine()
			}
		})
	})
	if disabled {
		b.Disabled(true)
	}
	if b.Clicked() {
		on()
	}
}

// chevron is the arrow of the previous and next buttons.
func chevron(c *ui.Context, t *ui.Theme, color ui.Color, right bool) {
	ui.Box(c).Size(16, 16).Draw(func(pt *ui.Painter, r ui.Rect) {
		cx, cy := r.X+r.W/2, r.Y+r.H/2
		var p ui.Path
		if right {
			p.MoveTo(cx-3, cy-3.5).LineTo(cx+3, cy).LineTo(cx-3, cy+3.5)
		} else {
			p.MoveTo(cx+3, cy-3.5).LineTo(cx-3, cy).LineTo(cx+3, cy+3.5)
		}
		pt.StrokePath(&p, 1.8, color)
	})
}

// pageRange is the pages to show: the first, the last, the current with
// its siblings, and dots where the rest collapsed, as BoardUI collapses
// them.
func pageRange(current, total, sibling int) []int {
	if sibling*2+5 >= total {
		out := make([]int, total)
		for i := range out {
			out[i] = i + 1
		}
		return out
	}
	left := max(current-sibling, 1)
	right := min(current+sibling, total)
	showLeft := left > 2
	showRight := right < total-2
	switch {
	case !showLeft && showRight:
		return append(inclusive(1, 3+2*sibling), DOTS, total)
	case showLeft && !showRight:
		out := []int{1, DOTS}
		return append(out, inclusive(total-(2+2*sibling), total)...)
	default:
		out := []int{1, DOTS}
		out = append(out, inclusive(left, right)...)
		return append(out, DOTS, total)
	}
}

// inclusive is the pages from lo to hi, both ends in.
func inclusive(lo, hi int) []int {
	out := make([]int, hi-lo+1)
	for i := range out {
		out[i] = lo + i
	}
	return out
}

// Package popover provides a shadcn/ui-style Popover: a panel that shows
// below the element Trigger draws, while *Open is true, and that a click
// on the trigger opens and closes. Clicking outside the panel or pressing
// Escape closes it.
//
//	popover.Popover(c, popover.Props{
//		Open: &app.help,
//		Trigger: func(c *ui.Context) *ui.Element {
//			return ui.Button(c, "Help")
//		},
//		Content: func(c *ui.Context) {
//			ui.Text(c, "Press the key for what you want.")
//		},
//	})
package popover

import "github.com/egoist/mygo/ui"

// Props describes the popover to draw.
type Props struct {
	// Open is whether the panel shows.
	Open *bool
	// Trigger draws the element the panel belongs to; a click on it
	// opens and closes the panel.
	Trigger func(c *ui.Context) *ui.Element
	// Content draws the panel, below the trigger.
	Content func(c *ui.Context)
	// Disabled keeps the trigger from opening the panel.
	Disabled bool
}

// Popover draws the trigger, and while *Open is true the panel below it.
// It returns the panel while it shows, and nil while it is closed, so a
// view can chain more calls on the panel.
func Popover(c *ui.Context, p Props) *ui.Element {
	anchor := p.Trigger(c)
	if p.Disabled {
		anchor.Disabled(true)
	} else if anchor.Clicked() {
		*p.Open = !*p.Open
	}
	return ui.Popover(c, anchor, p.Open, func() {
		if p.Content != nil {
			p.Content(c)
		}
	})
}

// Package progress provides a shadcn/ui-style progress bar with a label
// and a live readout, from the Progress of MyGo.
//
//	progress.Progress(c, progress.Props{
//		Value: 0.64,
//		Label: "Disk usage",
//	})
package progress

import (
	"fmt"

	"github.com/egoist/mygo/ui"
)

// Props describes the progress bar to draw.
type Props struct {
	// Value is the share filled, 0 to 1. A negative value shows
	// activity of unknown length, which moves on its own.
	Value float64
	// Label is the text above the bar, next to the readout.
	Label string
	// Format renders the readout; the default prints the percentage.
	Format func(v float64) string
	// Indeterminate shows activity of unknown length instead of Value.
	Indeterminate bool
}

// Progress draws the label, the readout and the bar, and returns the
// column. The readout follows the value as the app changes it, because
// the view builds every frame.
func Progress(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	format := p.Format
	if format == nil {
		format = func(v float64) string { return fmt.Sprintf("%.0f%%", v*100) }
	}
	return ui.Column(c).Gap(t.Space(0.5)).Children(func() {
		if p.Label != "" {
			ui.Row(c).Gap(t.Space(2)).Children(func() {
				ui.Text(c, p.Label).FontSize(t.FontSize * 0.875).Bold().TextColor(t.TextMuted)
				if !p.Indeterminate {
					ui.Text(c, format(p.Value)).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
				}
			})
		}
		value := p.Value
		if p.Indeterminate {
			value = -1
		}
		ui.Progress(c, value).FillWidth()
	})
}

// Package radio provides a shadcn/ui-style radio group: a column of
// options, of which one is chosen. The group is one stop of Tab; the
// arrows and Home and End choose among the options, as a radio group of
// the system does.
//
//	radio.Group(c, radio.Props[string]{
//		Selected: &size,
//		Options: []radio.Option[string]{
//			{Value: "sm", Label: "Small"},
//			{Value: "lg", Label: "Large"},
//		},
//	})
package radio

import "github.com/egoist/mygo/ui"

// Option is one choice of a group.
type Option[T comparable] struct {
	// Value is the value chosen into Selected.
	Value T
	// Label is the text next to the circle.
	Label string
}

// Props describes the group to draw.
type Props[T comparable] struct {
	// Selected is the chosen value; the group edits it, and Changed
	// reports a new one.
	Selected *T
	// Options are the choices, in order.
	Options []Option[T]
}

// Group draws a column of the options for props, the chosen one in the
// accent color, and returns the group, so a view can chain more calls on
// it.
func Group[T comparable](c *ui.Context, p Props[T]) *ui.Element {
	return ui.RadioGroup(c, func() {
		for _, o := range p.Options {
			ui.Radio(c, p.Selected, o.Value, o.Label)
		}
	})
}

// Package rangeslider provides a shadcn/ui-style range slider: a track
// with two knobs that set the low and the high of a range, with a label
// and a live readout, from the RangeSlider of MyGo.
//
//	rangeslider.RangeSlider(c, rangeslider.Props{
//		Low:    &minPrice,
//		High:   &maxPrice,
//		Min:    0,
//		Max:    1000,
//		Step:   50,
//		Label:  "Price",
//		Format: func(lo, hi float64) string { return fmt.Sprintf("$%.0f – $%.0f", lo, hi) },
//	})
package rangeslider

import (
	"fmt"

	"github.com/egoist/mygo/ui"
)

// Props describes the range slider to draw.
type Props struct {
	// Low and High are the bounds of the range, which the knobs set; Low
	// never passes High.
	Low, High *float64
	// Min and Max bound the whole range.
	Min, Max float64
	// Step snaps the values to multiples of it from Min, and shows tick
	// marks; 0 is continuous.
	Step float64
	// Label is the text above the track, next to the readout. It also
	// names the knobs, as "Price minimum" and "Price maximum".
	Label string
	// Format renders the readout from the two values; the default prints
	// them rounded.
	Format func(lo, hi float64) string
}

// RangeSlider draws the label, the readout and the track, and returns
// the column. The readout follows the knobs as the user drags, because
// the view builds every frame.
func RangeSlider(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	format := p.Format
	if format == nil {
		format = func(lo, hi float64) string { return fmt.Sprintf("%.0f – %.0f", lo, hi) }
	}
	return ui.Column(c).Gap(t.Space(0.5)).Children(func() {
		if p.Label != "" {
			ui.Row(c).Gap(t.Space(2)).Children(func() {
				ui.Text(c, p.Label).FontSize(t.FontSize * 0.875).Bold().TextColor(t.TextMuted)
				ui.Text(c, format(*p.Low, *p.High)).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
			})
		}
		r := ui.RangeSlider(c, p.Low, p.High, p.Min, p.Max, p.Step)
		r.Label(p.Label).FillWidth()
	})
}

// Package rating provides a shadcn/ui-style Rating: a row of stars that
// show and set a score, by a click or the arrows.
//
//	rating.Rating(c, rating.Props{Value: &stars, Max: 5})
package rating

import (
	"math"

	"github.com/egoist/mygo/ui"
)

// Props describes the rating to draw.
type Props struct {
	// Value is the score, from 0 to Max.
	Value *int
	// Max is the number of stars.
	Max int
	// ReadOnly draws the stars without letting the user change the score.
	ReadOnly bool
}

// Rating draws Max stars showing *Value, and returns the row, so a view
// can chain more calls on it. Label names it for assistive technology. A
// click on a star sets the score to it, and a click on the set star
// clears it; the arrows and Home and End move the score while focused.
// ReadOnly draws the stars as they are, without the interaction.
func Rating(c *ui.Context, p Props) *ui.Element {
	if p.ReadOnly {
		return readOnly(c, p)
	}
	return ui.Rating(c, p.Value, p.Max)
}

// readOnly draws the stars for ReadOnly. Why not MyGo's rating: it takes
// the pointer and the arrows, and no flag turns that off from outside.
func readOnly(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	e := ui.Row(c).Gap(t.Space(0.5)).Shrink(0).Role(ui.RoleSlider).
		Range(0, float64(p.Max), float64(*p.Value))
	star := t.FontSize * 1.25
	e.Children(func() {
		for i := range p.Max {
			b := ui.Box(c).Size(star, star).Shrink(0).Role(ui.RoleNone)
			b.Draw(func(pp *ui.Painter, r ui.Rect) {
				path := starPath(r)
				if i < *p.Value {
					pp.FillPath(path, t.Warning)
				} else {
					pp.StrokePath(path, 1.2, t.TextMuted)
				}
			})
		}
	})
	return e
}

// starPath returns a five-pointed star in r. Why not MyGo's helper: it
// is unexported, and the ten points are easy to place.
func starPath(r ui.Rect) *ui.Path {
	var path ui.Path
	cx, cy := r.X+r.W/2, r.Y+r.H/2+r.H*0.04
	outer, inner := r.W*0.48, r.W*0.2
	for i := range 10 {
		rad := outer
		if i%2 == 1 {
			rad = inner
		}
		a := float64(i)*math.Pi/5 - math.Pi/2
		x, y := cx+rad*float32(math.Cos(a)), cy+rad*float32(math.Sin(a))
		if i == 0 {
			path.MoveTo(x, y)
		} else {
			path.LineTo(x, y)
		}
	}
	path.Close()
	return &path
}

