		p.MoveTo(cx-5, cy-1).LineTo(cx+5, cy-1).LineTo(cx+5, cy+6).
			LineTo(cx-5, cy+6).Close()
		p.MoveTo(cx-5, cy-1).LineTo(cx-5, cy-4).LineTo(cx+5, cy-4).LineTo(cx+5, cy-1)
		p.MoveTo(cx, cy-1).LineTo(cx, cy+6)
