// Package stepper provides a shadcn/ui-style stepper: a number with two
// arrow buttons that step it, and a label and a live readout, from the
// Stepper of MyGo.
//
//	stepper.Stepper(c, stepper.Props{
//		Value: &port,
//		Min:   1024,
//		Max:   65535,
//		Step:  1,
//		Label: "Port",
//	})
package stepper

import (
	"fmt"

	"github.com/egoist/mygo/ui"
)

// Props describes the stepper to draw.
type Props struct {
	// Value is the number being set.
	Value *float64
	// Min and Max bound the value.
	Min, Max float64
	// Step is how much the arrows and the arrow keys move the value.
	Step float64
	// Label is the text above the control, next to the readout.
	Label string
	// Format renders the readout; the default prints the rounded value.
	Format func(v float64) string
}

// Stepper draws the label, the readout and the arrows, and returns the
// column. The readout follows the value as the user clicks or holds an
// arrow — it repeats, faster after a while — or presses the arrow keys,
// Home and End while the control has the focus, because the view builds
// every frame.
func Stepper(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	format := p.Format
	if format == nil {
		format = func(v float64) string { return fmt.Sprintf("%.0f", v) }
	}
	return ui.Column(c).Gap(t.Space(0.5)).Children(func() {
		if p.Label != "" {
			ui.Row(c).Gap(t.Space(2)).Children(func() {
				ui.Text(c, p.Label).FontSize(t.FontSize * 0.875).Bold().TextColor(t.TextMuted)
				ui.Text(c, format(*p.Value)).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
			})
		}
		s := ui.Stepper(c, p.Value, p.Min, p.Max, p.Step)
		s.Label(p.Label)
	})
}

// Package switcher provides a shadcn/ui-style switch with a label, from
// the Switch of MyGo. The package is named switcher because switch is a
// Go keyword.
//
//	switcher.Switch(c, switcher.Props{
//		On:    &dark,
//		Label: "Dark mode",
//	})
package switcher

import "github.com/egoist/mygo/ui"

// Props describes the switch to draw.
type Props struct {
	// On is the bool the switch toggles.
	On *bool
	// Label is the text beside the switch. It also names the switch for
	// tests: Click("Dark mode") toggles it.
	Label string
	// Disabled keeps the switch from being toggled.
	Disabled bool
	// Changed reports the new On, when the user toggled the switch.
	Changed func(on bool)
}

// Switch draws a row with the switch and its label, and returns it. The
// switch itself is clickable; the label is not.
func Switch(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	row := ui.Row(c).Gap(t.Space(2)).Children(func() {
		s := ui.Switch(c, p.On)
		if p.Label != "" {
			s.Label(p.Label)
		}
		if p.Disabled {
			s.Disabled(true)
		}
		if p.Changed != nil && s.Changed() {
			p.Changed(*p.On)
		}
		if p.Label != "" {
			ui.Text(c, p.Label)
		}
	})
	return row
}

// Package table provides a shadcn/ui-style data table for the MyGo native
// toolkit, on top of the Table of MyGo: a bordered box with a header
// band, rows that highlight under the pointer, and a chosen row in the
// accent color. The sort, the choice and the column layout live in the
// ListState the caller owns, as the state of any control does.
//
//	table.Table(c, table.Props{
//		State:   list, // &ui.ListState, owned by the view
//		Columns: []ui.TableColumn{{Title: "Name", Sortable: true}, {Title: "Size", Align: ui.End, Sortable: true}},
//		Rows:    len(rows),
//		Cell: func(row, col int) {
//			ui.Text(c, rows[row][col]).SingleLine()
//		},
//	}).Grow(1)
package table

import "github.com/egoist/mygo/ui"

// Props describes the table to draw.
type Props struct {
	// State is the ListState the table keeps its choice, its sort and
	// its column layout in; the caller owns it and keeps it across
	// frames. A nil State works, but then rows cannot be chosen, sorted
	// or rearranged.
	State *ui.ListState
	// Columns are the columns of the table. The user resizes them by
	// dragging the edges of their headers, and moves them by dragging
	// the headers.
	Columns []ui.TableColumn
	// Rows is the number of rows the table draws. It builds only those
	// in view, so a table of thousands is as cheap as one of ten.
	Rows int
	// Cell builds the content of the cell of a row and a column, usually
	// a Text.
	Cell func(row, col int)
}

// Table draws a table and returns it, so a view can chain more calls on
// it, such as Grow and Submitted.
func Table(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	e := ui.Table(c, p.State, p.Columns, p.Rows, p.Cell)
	e.Background(t.Background).Border(1, t.Border).Radius(t.Radius)
	// The header band: MyGo's table draws no face for its header row,
	// which the band gives it, as the muted band of shadcn/ui.
	//
	// Why not set a background on the header itself: it is built inside
	// MyGo's Table, out of reach, so the band is drawn behind it, the
	// height of the header the table sets.
	e.Draw(func(pp *ui.Painter, r ui.Rect) {
		pp.Fill(ui.Rect{X: r.X, Y: r.Y, W: r.W, H: t.Space(8)}, t.Surface, 0)
	})
	return e
}

// Package tabs provides a shadcn/ui-style tab list: a row of triggers
// that switch a pane of content, of which one is chosen. The chosen one
// shows in the text color, with a bar in the accent color under it; the
// others show muted, over a hairline. Draw the content of the chosen tab
// yourself, next to the list.
//
//	tabs.Tabs(c, tabs.Props{Selected: &tab, Labels: []string{"General", "About"}})
//	switch *tab {
//	case 0:
//		general(c)
//	case 1:
//		about(c)
//	}
package tabs

import "github.com/egoist/mygo/ui"

// Props describes the tab list to draw.
type Props struct {
	// Selected is the index of the chosen tab; the list edits it, and a
	// click or the arrow keys choose.
	Selected *int
	// Labels are the tabs, in order.
	Labels []string
}

// Tabs draws a list of tabs for props: the chosen one in the text color
// with an accent bar under it, the others muted, on a hairline, as the
// tabs of shadcn/ui. It returns the list, so a view can chain more calls
// on it.
func Tabs(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	tp := ui.TabsBase(c, p.Selected, len(p.Labels))
	list := tp.List.Gap(0)
	// The hairline sits behind the tabs, so the accent bar of the chosen
	// tab draws over it.
	list.Draw(func(pp *ui.Painter, r ui.Rect) {
		pp.Fill(ui.Rect{X: r.X, Y: r.Y + r.H - 1, W: r.W, H: 1}, t.Border, 0)
	})
	list.Children(func() {
		for i, label := range p.Labels {
			tab := tp.Tab(i).Padding(t.Space(2), t.Space(3)).FocusRing(false)
			on := i == *p.Selected
			tab.TextColor(t.TextMuted)
			if on {
				tab.TextColor(t.Text).FontWeight(600)
			}
			tab.DrawOver(func(pp *ui.Painter, r ui.Rect) {
				if on {
					in, h := t.Space(1.5), t.Space(0.5)
					pp.Fill(ui.Rect{X: r.X + in, Y: r.Y + r.H - h, W: r.W - 2*in, H: h}, t.Accent, h/2)
				}
			})
			tab.Children(func() { ui.Text(c, label).SingleLine() })
		}
	})
	return list
}

// Package textarea provides a shadcn/ui-style multi-line text field for
// the MyGo native toolkit.
//
//	textarea.Textarea(c, textarea.Props{
//		Value:       &notes,
//		Placeholder: "Write your notes here…",
//	})
package textarea

import "github.com/egoist/mygo/ui"

// Props describes the text area to draw.
type Props struct {
	// Value is the text being edited.
	Value *string
	// Placeholder shows in the empty field, in the muted color.
	Placeholder string
	// Disabled keeps the field from being edited.
	Disabled bool
	// Rows is the height of the field in lines of text; the default is 4.
	Rows int
}

// Textarea draws a multi-line field editing *Value and returns it, so a
// view can chain more calls on it. It fills the width of its container.
func Textarea(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	if p.Rows <= 0 {
		p.Rows = 4
	}
	e := ui.TextArea(c, p.Value)
	e.Placeholder(p.Placeholder)
	e.FillWidth()
	// MyGo's text area comes with a floor of 20 units, near four lines;
	// MinHeight replaces it, so Rows can ask for any height.
	//
	// Why not the line height of the text engine: it is a metric of the
	// font, internal to MyGo, so we approximate it with CSS's standard
	// line height of 1.4em, as Rem returns. The box grows by the padding
	// of the field, 1.5 units top and bottom.
	e.MinHeight(float32(p.Rows)*t.Rem(1.4) + t.Space(3))
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package thinking provides the AgentThinking indicator of BoardUI for
// the MyGo native toolkit: a row of a working indicator, a label and an
// elapsed timer, drawn while an agent works on a response. The indicator
// animates by itself, repainting without rebuilding the view.
//
//	thinking.Thinking(c, thinking.Props{Label: "Thinking"})
package thinking

import (
	"fmt"
	"math"
	"time"

	"github.com/egoist/mygo/ui"
)

// Variant is the pattern of the working indicator.
type Variant string

// The variants of the indicator, from BoardUI's AgentThinking.
const (
	// Wave sweeps a diagonal wavefront across a dot grid.
	Wave Variant = "wave"
	// Spin orbits a bright head around a dot grid.
	Spin Variant = "spin"
	// Stars twinkles a few sparkles.
	Stars Variant = "stars"
	// Infinity sweeps a comet along a figure-eight.
	Infinity Variant = "infinity"
)

// Tone is the color of the indicator and the label.
type Tone string

// The tones of the indicator and the label.
const (
	Subtle  Tone = "subtle"
	Default Tone = "default"
	Primary Tone = "primary"
	Accent  Tone = "accent"
)

// Props describes the indicator to draw.
type Props struct {
	// Variant is the pattern of the indicator; the zero value is Wave.
	Variant Variant
	// Label is the status text, such as "Thinking" or "Searching the docs".
	Label string
	// Tone colors the indicator and the label. The zero value picks the
	// default tone of the variant, which is Subtle for Stars and Default
	// for the rest.
	Tone Tone
	// ShowTimer draws the time since Started after the label.
	ShowTimer bool
	// Started is when the work began, for the timer. The zero value
	// draws 0.0s.
	Started time.Time
}

// Thinking draws the indicator and returns it.
func Thinking(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	color := toneColor(t, p.Tone)
	size := t.FontSize
	return ui.Row(c).AlignItems(ui.Center).Gap(10).Children(func() {
		indicator(c, p.Variant, color)
		ui.Text(c, p.Label).FontSize(size).TextColor(color)
		if p.ShowTimer {
			ui.Box(c).Shrink(0).Width(48).Draw(func(pt *ui.Painter, r ui.Rect) {
				base := p.Started
				if base.IsZero() {
					base = pt.Now()
				}
				elapsed := pt.Now().Sub(base)
				s := fmt.Sprintf("%.1fs", elapsed.Seconds())
				pt.After(100 * time.Millisecond)
				pt.Text(r.X, r.Y+r.H/2+size*0.35, s, size*0.85, t.TextMuted)
			})
		}
	})
}

// toneColor maps a tone to a theme color; the two muted tones share the
// muted text color, as the theme has no secondary text color.
func toneColor(t *ui.Theme, tone Tone) ui.Color {
	switch tone {
	case Primary:
		return t.Text
	case Accent:
		return t.Accent
	}
	return t.TextMuted
}

// indicator draws the animated mark of the variant.
func indicator(c *ui.Context, v Variant, color ui.Color) *ui.Element {
	switch v {
	case Spin:
		return dotGrid(c, true, color)
	case Stars:
		return stars(c, color)
	case Infinity:
		return infinity(c, color)
	default: // Wave
		return dotGrid(c, false, color)
	}
}

// dotGrid draws the wave or spin pattern: a 3x3 grid of dots whose
// opacities follow a phase front across the grid, in a wave along the
// diagonals or a head orbiting the centre.
func dotGrid(c *ui.Context, spin bool, color ui.Color) *ui.Element {
	const size, gap = 4, 2
	e := ui.Box(c).Size(20, 20).Shrink(0).Draw(func(p *ui.Painter, r ui.Rect) {
		phase := float64(p.Now().UnixMilli()%80) / 80
		// The 16px grid sits centred in the 20px box, with a 2px margin.
		cx, cy := r.X+2, r.Y+2
		for row := 0; row < 3; row++ {
			for col := 0; col < 3; col++ {
				s := waveScalar(col, row)
				if spin {
					s = spinScalar(col, row)
				}
				behind := math.Mod(phase-s+1, 1)
				lit := math.Pow(math.Max(0, 1-behind/0.3), 1.5)
				alpha := float32(0.12 + 0.88*lit)
				x := cx + float32(col)*(size+gap)
				y := cy + float32(row)*(size+gap)
				var dot ui.Path
				dot.Circle(x+size/2, y+size/2, size/2)
				p.FillPath(&dot, color.Alpha(alpha))
			}
		}
		p.After(80 * time.Millisecond)
	})
	return e
}

// waveScalar is how far along the wave's travel direction a cell sits:
// the front walks the diagonals from top-left to bottom-right. The scalar
// is compressed below 1 so the wrap reads as the front leaving and
// re-entering the grid.
func waveScalar(col, row int) float64 {
	return float64(col+row) / (2 * 2) * (3.0 / 4.0)
}

// spinScalar is the angle of a cell around the grid centre, as a phase
// in [0, 1), so the bright head orbits clockwise.
func spinScalar(col, row int) float64 {
	return math.Mod(math.Atan2(float64(row-1), float64(col-1))/(2*math.Pi)+1, 1)
}

// stars twinkles five four-point sparkles, each on its own phase, so the
// sky does not pulse in unison.
func stars(c *ui.Context, color ui.Color) *ui.Element {
	// Positions as percentages of the box, like BoardUI's STAR_LAYOUT.
	layout := []struct{ x, y, scale float64 }{
		{50, 46, 1}, {18, 22, 0.55}, {82, 26, 0.45}, {78, 76, 0.55}, {22, 78, 0.4},
	}
	const period = 1400.0 // ms per twinkle
	e := ui.Box(c).Size(21, 21).Shrink(0).Draw(func(p *ui.Painter, r ui.Rect) {
		ms := float64(p.Now().UnixMilli())
		for i, s := range layout {
			phase := math.Mod(ms/period+float64(i)*0.7/5, 1)
			alpha := float32(0.25 + 0.75*math.Pow(math.Sin(2*math.Pi*phase), 2))
			arm := float32(3.5 * s.scale)
			x := r.X + float32(s.x/100)*r.W
			y := r.Y + float32(s.y/100)*r.H
			var spark ui.Path
			spark.MoveTo(x-arm, y).LineTo(x+arm, y)
			spark.MoveTo(x, y-arm).LineTo(x, y+arm)
			p.StrokePath(&spark, 1.2, color.Alpha(alpha))
			var core ui.Path
			core.Circle(x, y, 0.8)
			p.FillPath(&core, color.Alpha(alpha))
		}
		p.After(100 * time.Millisecond)
	})
	return e
}

// infinity draws a figure-eight faintly and sweeps a comet along it: the
// head and the fading dots of its trail, on the curve x = A sin t,
// y = B sin 2t, so the loop reads as a horizontal eight.
func infinity(c *ui.Context, color ui.Color) *ui.Element {
	const lap = 1200.0 // ms per lap
	e := ui.Box(c).Size(24, 16).Shrink(0).Draw(func(p *ui.Painter, r ui.Rect) {
		cx, cy := r.X+r.W/2, r.Y+r.H/2
		a, b := r.W/2-2, r.H/2-2
		at := func(t float64) (float32, float32) {
			return cx + float32(float64(a)*math.Sin(t)), cy + float32(float64(b)*math.Sin(2*t))
		}
		// The faint whole, one sampled path.
		var eight ui.Path
		first := true
		for i := 0; i <= 128; i++ {
			x, y := at(2 * math.Pi * float64(i) / 128)
			if first {
				eight.MoveTo(x, y)
				first = false
			} else {
				eight.LineTo(x, y)
			}
		}
		p.StrokePath(&eight, 2, color.Alpha(0.15))
		// The comet: a bright head and fading dots behind it along the path.
		ph := math.Mod(float64(p.Now().UnixMilli())/lap, 1)
		for i := 3; i >= 0; i-- {
			t := 2*math.Pi*ph - float64(i)*0.18
			x, y := at(t)
			var dot ui.Path
			dot.Circle(x, y, float32(2-0.45*float64(i)))
			p.FillPath(&dot, color.Alpha(float32(0.55-0.14*float64(i))))
		}
		p.After(40 * time.Millisecond)
	})
	return e
}

