// Package toolbar provides a row of actions along the top of a window,
// from the mygo Toolbar widget. The controls are one stop of Tab; those
// that do not fit go, from the last, into a menu at the end.
package toolbar

import (
	"github.com/egoist/mygo/ui"
)

// Props configure the toolbar.
type Props struct {
	// Label names the toolbar for assistive technology.
	Label string
	// Children builds the controls: buttons, toggles, toggle groups
	// and menu buttons, which take no face of their own until hovered.
	// A Spacer pushes the controls after it to the end.
	Children func(c *ui.Context)
	// Disabled disables the controls of the toolbar.
	Disabled bool
}

// Toolbar draws the controls in a row, one stop of Tab, with Left and
// Right moving the focus among them, and Home and End to the first and
// the last.
func Toolbar(c *ui.Context, p Props) *ui.Element {
	tb := ui.Toolbar(c, func() {
		if p.Children != nil {
			p.Children(c)
		}
	})
	if p.Label != "" {
		tb.Label(p.Label)
	}
	if p.Disabled {
		tb.Disabled(true)
	}
	return tb
}

// Package tooltip provides a shadcn/ui-style Tooltip: a hint that shows
// once the pointer has rested on the anchor for a moment, and goes as
// the pointer leaves it or presses it, and with Escape, until the pointer
// or the focus comes back. The anchor is any element a view has already
// built; Tooltip attaches the hint to it.
//
//	save := ui.Button(c, "Save")
//	tooltip.Tooltip(c, tooltip.Props{Anchor: save, Text: "Save the file"})
package tooltip

import "github.com/egoist/mygo/ui"

// Props describes the tooltip to draw.
type Props struct {
	// Anchor is the element the tip belongs to.
	Anchor *ui.Element
	// Text is what the tip says.
	Text string
	// Disabled keeps the tip away, even as the pointer rests.
	Disabled bool
}

// Tooltip attaches a hint to the anchor and returns it, so a view can
// chain more calls on it.
func Tooltip(c *ui.Context, p Props) *ui.Element {
	if p.Disabled {
		return p.Anchor
	}
	return p.Anchor.Tooltip(p.Text)
}

// Package tree provides a hierarchical list whose branches open and
// close, from the mygo Tree and TreeItem widgets. A node with Children
// is a branch, one without them a leaf. Choosing a node highlights it
// and runs its action.
package tree

import (
	"github.com/egoist/mygo/ui"
)

// Item is one node of the tree.
type Item struct {
	// Label is the text of the node. Labels must differ, as the chosen
	// node is found by its label.
	Label string
	// Open opens and closes a branch. A branch — an item with Children —
	// needs it; the tree flips it when the arrow is clicked.
	Open *bool
	// Children are the nodes inside the branch.
	Children []Item
	// Action runs when the node is chosen, by a click or Enter.
	Action func()
}

// Props configure the tree.
type Props struct {
	// Items are the nodes of the tree.
	Items []Item
	// Chosen is the label of the chosen node. The tree sets it when a
	// node is chosen and shows the node highlighted. nil keeps the tree
	// from highlighting.
	Chosen *string
	// Disabled keeps the tree from opening or choosing nodes.
	Disabled bool
}

// Tree draws the items as a tree. A click on the arrow of a branch
// opens or closes it; a click on a node, or Enter, chooses it. While a
// node has the keyboard focus, Up and Down move around it, Right opens
// it or moves to its first child, and Left closes it or moves to its
// parent.
func Tree(c *ui.Context, p Props) *ui.Element {
	t := ui.Tree(c, func() {
		for _, it := range p.Items {
			build(c, it, p)
		}
	})
	if p.Disabled {
		t.Disabled(true)
	}
	return t
}

// build draws a node, the nodes inside it, and applies the choice.
func build(c *ui.Context, it Item, p Props) {
	item := ui.TreeItem(c, it.Label, it.Open, func() {
		for _, child := range it.Children {
			build(c, child, p)
		}
	})
	if p.Chosen != nil {
		item.Selected(*p.Chosen == it.Label)
	}
	if item.Clicked() {
		if p.Chosen != nil {
			*p.Chosen = it.Label
		}
		if it.Action != nil {
			it.Action()
		}
	}
}
